    "✨ ¡Te damos la bienvenida a ¡Suelta! ✨": "✨ ¡Te damos la bienvenida a ¡Suelta! ✨",
    "Este es tu santuario digital de autodescubrimiento y liberación emocional. Integraremos la biodescodificación, la epigenética y las constelaciones para sanar el origen emocional de tus tensiones. Pulsa 'Comenzar Tour' para iniciar.": "Este es tu santuario digital de autodescubrimiento y liberación emocional. Integraremos la biodescodificación, la epigenética y las constelaciones para sanar el origen emocional de tus tensiones. Pulsa 'Comenzar Tour' para iniciar.",
    "🔍 Paso 1: Elige tu Sintonización": "🔍 Paso 1: Elige tu Sintonización",
    "En la pantalla de Inicio, selecciona tus áreas de sintonía de hoy. ¡Pruébalo ahora! Toca la opción 'Cuéntame tu historia' resaltada abajo.": "En la pantalla de Inicio, selecciona tus áreas de sintonía de hoy. ¡Pruébalo ahora! Toca la opción 'Cuéntame tu historia' resaltada abajo.",
