    "🚀 Paso 2: El Botón Continuar": "🚀 Paso 2: El Botón Continuar",
    "Cuando selecciones al menos una opción, el botón de Continuar se iluminará con un brillo ámbar especial 👇 para llevarte al análisis completo.": "Cuando selecciones al menos una opción, el botón de Continuar se iluminará con un brillo ámbar especial 👇 para llevarte al análisis completo.",
