    "📅 Paso 3: Reto de 21 Días": "📅 Paso 3: Reto de 21 Días",
    "Tu mente requiere 21 días para reprogramar viejos patrones. En la pestaña 'Mi Reto' tienes acceso a audios diarios, afirmaciones y progreso áureo.": "Tu mente requiere 21 días para reprogramar viejos patrones. En la pestaña 'Mi Reto' tienes acceso a audios diarios, afirmaciones y progreso áureo.",
    "Toca la pestaña 'Mi Reto' en la barra inferior.": "Toca la pestaña 'Mi Reto' en la barra inferior.",
    "✍️ Paso 4: Escribe tu Reflexión Diaria": "✍️ Paso 4: Escribe tu Reflexión Diaria",
    "Cada día del Reto incluye un espacio de escritura terapéutica. Intenta escribir cómo te sientes hoy en la casilla de texto.": "Cada día del Reto incluye un espacio de escritura terapéutica. Intenta escribir cómo te sientes hoy en la casilla de texto.",
    "Escribe al menos 3 letras en la casilla '¿Cómo te sientes con esta revelación?'.": "Escribe al menos 3 letras en la casilla '¿Cómo te sientes con esta revelación?'.",
