    "Tu respuesta automática al estrés suele ser entrar en acción: buscas resolver, controlar o defenderte. Esta respuesta te ha hecho eficiente, pero puede agotarte y tensar tus relaciones. Recuerda que no todo requiere una respuesta inmediata.": "Tu respuesta automática al estrés suele ser entrar en acción: buscas resolver, controlar o defenderte. Esta respuesta te ha hecho eficiente, pero puede agotarte y tensar tus relaciones. Recuerda que no todo requiere una respuesta inmediata.",
    "Congelación (parálisis / retiro)": "Congelación (parálisis / retiro)",
    "Tu sistema tiende a pausar o desconectar cuando la intensidad sube: te cuesta decidir o prefieres aislarte. Es una forma de proteger tu energía, pero puede dejarte con sensación de bloqueo. Empezar por acciones minúsculas ayuda a descongelar.": "Tu sistema tiende a pausar o desconectar cuando la intensidad sube: te cuesta decidir o prefieres aislarte. Es una forma de proteger tu energía, pero puede dejarte con sensación de bloqueo. Empezar por acciones minúsculas ayuda a descongelar.",
