    "Apego seguro en desarrollo": "Apego seguro en desarrollo",
    "Muestras una base sólida de confianza: puedes pedir ayuda, tolerar la distancia y expresar lo que sientes sin tanto miedo. Sigue cultivando este equilibrio entre cuidar de ti y dejar que otros se acerquen.": "Muestras una base sólida de confianza: puedes pedir ayuda, tolerar la distancia y expresar lo que sientes sin tanto miedo. Sigue cultivando este equilibrio entre cuidar de ti y dejar que otros se acerquen.",
    "Apego ansioso / necesidad de reaseguro": "Apego ansioso / necesidad de reaseguro",
    "Tiendes a hipervigilar los vínculos: el distanciamiento del otro activa tu alarma de abandono. Tu trabajo principal es construir seguridad interna — aprender a ser tu propio refugio antes de buscarlo afuera.": "Tiendes a hipervigilar los vínculos: el distanciamiento del otro activa tu alarma de abandono. Tu trabajo principal es construir seguridad interna — aprender a ser tu propio refugio antes de buscarlo afuera.",
    "Apego evitativo / autosuficiencia": "Apego evitativo / autosuficiencia",
    "Has aprendido a depender principalmente de ti mismo/a, a veces a costa de tu vulnerabilidad. La autosuficiencia te protegió en el pasado, pero abrir pequeñas rendijas de confianza puede enriquecer mucho tus relaciones.": "Has aprendido a depender principalmente de ti mismo/a, a veces a costa de tu vulnerabilidad. La autosuficiencia te protegió en el pasado, pero abrir pequeñas rendijas de confianza puede enriquecer mucho tus relaciones.",
    "Apego desorganizado / ambivalente": "Apego desorganizado / ambivalente",
    "Experimentas un vaivén entre desear mucha cercanía y temerla cuando llega. Es un patrón comprensible si en tu historia la cercanía estuvo ligada al dolor. La paciencia contigo y la coherencia en tus límites son tu medicina.": "Experimentas un vaivén entre desear mucha cercanía y temerla cuando llega. Es un patrón comprensible si en tu historia la cercanía estuvo ligada al dolor. La paciencia contigo y la coherencia en tus límites son tu medicina.",
