    "El tarot no predice: refleja lo que quizás ya intuyes.": "El tarot no predice: refleja lo que quizás ya intuyes.",
    "Trabajaremos con los 22 arcanos mayores, que trazan el llamado “Viaje del Loco”: un recorrido simbólico desde el primer paso lleno de fe hasta la plenitud. Cada carta es un arquetipo, un espejo de una etapa de la vida.": "Trabajaremos con los 22 arcanos mayores, que trazan el llamado “Viaje del Loco”: un recorrido simbólico desde el primer paso lleno de fe hasta la plenitud. Cada carta es un arquetipo, un espejo de una etapa de la vida.",
