    "Busca una posición cómoda, sentada o acostada, y cierra los ojos si te sientes segura.": "Find a comfortable position, seated or lying down, and close your eyes if you feel safe.",
    "Lleva tu atención a los pies. Nota su peso, su temperatura, sin cambiar nada, solo notando.": "Bring your attention to your feet. Notice their weight, their temperature, changing nothing, just noticing.",
    "Sube la atención a las piernas y las caderas. Si hay tensión, no la fuerces a irse — solo reconócela.": "Move your attention up to your legs and hips. If there is tension, do not force it away — just acknowledge it.",
    "Ahora el abdomen and el pecho. Sigue el ritmo natural de tu respiración, sin modificarlo.": "Now the abdomen and the chest. Follow the natural rhythm of your breath, without modifying it.",
    "Lleva la atención a los hombros. Es común que carguen tensión sin que te des cuenta — déjalos caer un poco.": "Bring your attention to your shoulders. It is common for them to carry tension unnoticed — let them drop a little.",
    "Por último, la cara y la cabeza. Suelta la mandíbula, suelta la frente.": "Lastly, the face and head. Release the jaw, soften the forehead.",
    "Antes de abrir los ojos, nota cómo se siente todo tu cuerpo junto, de una vez.": "Before opening your eyes, notice how your entire body feels all at once.",
