    "Hola": "Hello",
    "Este es un espacio para escucharte sin prisa. Elige una, dos o las tres opciones — cuanto más te permitas compartir, más clara será la luz que ilumine tu camino de vuelta a ti.": "This is a space to listen to yourself without rush. Choose one, two, or all three options — the more you allow yourself to share, the clearer the light that guides your way back to yourself will be.",

    // Onboarding Slides
    "El espacio para soltar": "The space to release",
    "¡Suelta! es tu refugio digital. Te ayudamos a escuchar tus emociones, entender tus síntomas y reconectar con tu calma desde la raíz.": "Let Go! is your digital sanctuary. We guide you to listen to your emotions, understand bodily sensations, and reconnect with your inner peace.",
    "Exploración profunda": "Deep exploration",
    "Obtén una lectura emocional de lo que sientes. Combinamos enfoques terapéuticos con perspectivas simbólicas para brindarte claridad.": "Get an emotional reading of what you feel. We combine therapeutic approaches with symbolic perspectives to bring you clarity.",
    "El Diálogo Humano": "The Human Dialogue",
    "Nada reemplaza el valor de conectar con otra persona. Te damos herramientas para transformar tus conversaciones en encuentros reales.": "Nothing replaces the value of connecting with another person. We give you tools to transform your conversations into genuine encounters.",
    "Un viaje de 21 días": "A 21-day journey",
    "Acompáñanos en un reto guiado de 21 días. Lleva un diario de bienestar, forma nuevos hábitos y encuentra tu centro nuevamente.": "Join us on a guided 21-day challenge. Keep a wellness journal, form new habits, and find your center once again.",

