    "No pudimos encontrar una decodificación exacta para tu búsqueda. Intenta buscar términos simples como 'cabeza', 'espalda', 'estómago' o 'ansiedad'.": "We couldn't find an exact emotional decoding for your search. Try simple terms like 'headache', 'back', 'stomach', or 'anxiety'.",

    // 21-Day Challenge Practices
    "Escribe la frase exacta que te dices cuando aparece el malestar. Léela en voz alta y pregúntate si es del todo cierta.": "Write the exact phrase you say to yourself when discomfort arises. Read it aloud and ask yourself if it is absolutely true.",
    "Identifica en qué momento del día sientes más tensión. Solo obsérvalo, sin cambiar nada aún.": "Identify at what time of the day you feel the most tension. Just observe it, without changing anything yet.",
    "Recuerda la primera vez que sentiste algo parecido a lo que vives hoy. ¿Qué edad tenías?": "Remember the first time you felt something similar to what you are experiencing today. How old were you?",
    "Hoy, cada vez que aparezca el malestar, respira hondo tres veces antes de reaccionar.": "Today, every time discomfort appears, take three deep breaths before reacting.",
    "Escribe una carta que no vas a enviar, dirigida a quien crees que está ligado a este conflicto.": "Write a letter that you will not send, addressed to the person you believe is connected to this conflict.",
    "Nombra en voz alta lo que sientes, usando la frase: \u201cme permito sentir…\u201d.": "Name out loud what you are feeling, using the phrase: \u201cI allow myself to feel...\u201d.",
    "Haz una pausa de 5 minutos hoy solo para ti, sin pantallas ni tareas.": "Take a 5-minute pause today just for yourself, without screens or tasks.",
    "Observa tu cuerpo: ¿dónde se aloja la emoción? Ponle una mano encima un minuto.": "Observe your body: where is the emotion located? Place a hand over it for one minute.",
    "Escribe tres cosas que este malestar ha intentado protegerte o enseñarte.": "Write three things that this discomfort has tried to protect you from or teach you.",
    "Perdónate por algo pequeño de hoy. Dilo en voz alta.": "Forgive yourself for something small today. Say it out loud.",
    "Reconoce a alguien de tu familia cuyo destino sientes que cargas. Solo míralo con respeto.": "Acknowledge someone in your family whose destiny you feel you are carrying. Just look at them with respect.",
    "Hoy di \u201cno\u201d a algo que normalmente aceptarías por costumbre.": "Today say \u201cno\u201d to something you would normally accept out of habit.",
    "Agradece a tu cuerpo por avisarte, en lugar de pelearte con el síntoma.": "Thank your body for warning you, instead of fighting the symptom.",
    "Escribe cómo te gustaría sentirte dentro de un año, en presente.": "Write how you would like to feel in one year, in the present tense.",
    "Suelta un objeto, una idea o una rutina que ya no te sirve.": "Let go of an object, an idea, or a routine that no longer serves you.",
    "Dedica hoy a mirar lo que sí funciona en tu vida, por pequeño que sea.": "Dedicate today to looking at what does work in your life, however small it may be.",
    "Repite tu frase de sanación mirándote al espejo.": "Repeat your healing phrase looking at yourself in the mirror.",
    "Haz las paces simbólicamente con una versión más joven de ti.": "Symbolically make peace with a younger version of yourself.",
    "Comparte con alguien de confianza una parte de este proceso.": "Share part of this process with someone you trust.",
    "Escribe qué ha cambiado en ti desde el día 1, aunque sea sutil.": "Write down what has changed in you since day 1, even if it is subtle.",
    "Celebra haber llegado hasta aquí. Escribe una promesa amable para tu futuro.": "Celebrate having made it this far. Write a kind promise for your future.",

