    // Recommendations Expresión
    "Dedica 5 minutos al inicio del día para escribir de forma libre (sin levantar la pluma del papel) para drenar la rumiación.": "Spend 5 minutes at the start of the day writing freely (without lifting the pen from the paper) to drain rumination.",
    "Acompaña tus prácticas de diario con solfeo de 396Hz para disolver bloqueos y miedos inconscientes.": "Accompany your journal practices with 396Hz solfeggio to dissolve blocks and unconscious fears.",
    "Practica la respiración de caja (inhalar 4, retener 4, exhalar 4, retener 4) antes de iniciar tus reflexiones.": "Practice box breathing (inhale 4, hold 4, exhale 4, hold 4) before beginning your reflections.",
    "Utiliza la escritura como un espacio de compasión, permitiéndote llorar o plasmar tus penas sin culpas ni juicios.": "Use writing as a space of self-compassion, allowing yourself to cry or record your grief without guilt or judgment.",
    "Sintoniza la frecuencia de solfeo de 528Hz para promover la restauración celular de tu estado de ánimo y el amor propio.": "Tune into the 528Hz solfeggio frequency to promote cell restoration of your mood and self-love.",
    "Agrega una sección fija al final de cada escrito donde menciones una sola cosa por la que sientas aprecio sincero hoy.": "Add a permanent section at the end of each writing where you mention just one thing for which you feel sincere appreciation today.",
    "Escribe sobre tu enojo de forma explícita, arrugando o rompiendo el papel después (si es físico) para dar salida física a la emoción.": "Write about your anger explicitly, wrinkling or tearing up the paper afterward (if physical) to give a physical outlet to the emotion.",
    "Usa solfeo de 417Hz para sintonizar con la limpieza de energías estancadas y facilitar la aceptación del cambio.": "Use 417Hz solfeggio to tune into clearing stagnant energies and facilitate acceptance of change.",
    "Introduce pausas conscientes de silencio absoluto de 1 minuto antes de responder a situaciones tensas.": "Introduce conscious pauses of absolute silence for 1 minute before responding to tense situations.",
    "¡Excelente balance! Expande tu bienestar describiendo a detalle los rostros, olores y sensaciones de los momentos felices.": "Excellent balance! Expand your well-being by describing in detail the faces, scents, and sensations of happy moments.",
    "Sintoniza frecuencias de 639Hz y 852Hz para elevar tu intuición y fortalecer tus conexiones interpersonales.": "Tune into 639Hz and 852Hz frequencies to raise your intuition and strengthen your interpersonal connections.",
    "Comparte un pensamiento de gratitud con alguien de tu entorno para contagiar y amplificar tu bienestar.": "Share a thought of gratitude with someone in your circle to spread and amplify your well-being.",
    "Mantén la constancia en tu registro diario. La regularidad es la clave para la auto-consciencia.": "Keep consistency in your daily logging. Regularity is the key to self-awareness.",
    "Prueba variar los temas de tu diario alternando entre relatos de tu día y descripciones puramente emocionales o corporales.": "Try varying the themes of your journal, alternating between stories of your day and purely emotional or physical descriptions.",
    "Usa solfeo de 432Hz o 528Hz de fondo para sintonizar con los armónicos naturales del entorno.": "Use 432Hz or 528Hz solfeggio in the background to tune in with the natural harmonics of your surroundings.",

    // Recommendations Entorno
    "Crea una rutina de desconexión digital absoluta al menos 45 minutos antes de dormir.": "Create a routine of absolute digital disconnection at least 45 minutes before sleeping.",
    "Introduce difusores con esencia de lavanda, bergamota o manzanilla en tu espacio de descanso.": "Introduce diffusers with lavender, bergamot, or chamomile oil in your relaxation space.",
    "Mantén luces cálidas y tenues por la noche para indicarle a tu sistema nervioso que está seguro.": "Keep warm and dim lights at night to signal your nervous system that it is safe.",
    "Busca activamente el contacto con la luz natural durante las mañanas (camina al menos 10 minutos bajo el sol).": "Actively seek contact with natural light in the mornings (walk at least 10 minutes under the sun).",
    "Introduce plantas de interior 🌱 o flores frescas en tu espacio vital para renovar el aire y la energía visual.": "Introduce indoor plants 🌱 or fresh flowers in your living space to renew the air and visual energy.",
    "Escucha sonidos de agua corriente (lluvia, fuentes) de fondo para facilitar el flujo emocional.": "Listen to running water sounds (rain, fountains) in the background to facilitate emotional flow.",
    "Asegura el orden visual en tu mesa o escritorio, ya que el desorden físico incrementa la reactividad mental.": "Ensure visual order on your table or desk, as physical clutter increases mental reactivity.",
    "Crea un 'rincón de descarga': un lugar cómodo con cojines donde puedas respirar o descansar sin ruidos molestos.": "Create a 'release corner': a comfortable spot with cushions where you can breathe or rest without disturbing noises.",
    "Aromatiza tu espacio con esencias cítricas (limón, naranja) para elevar la claridad mental y refrescar la atmósfera.": "Scent your space with citrus oils (lemon, orange) to elevate mental clarity and refresh the atmosphere.",
    "Conserva fotos de momentos alegres, seres queridos o frases inspiradoras a la vista en tu habitación.": "Keep photos of happy moments, loved ones, or inspiring quotes in view in your room.",
    "Ventila tus espacios habitacionales diariamente para permitir la renovación constante de la energía vital.": "Ventilate your living spaces daily to allow constant renewal of vital energy.",
    "Utiliza sonidos de cuencos de cuarzo o campanas koshi para purificar acústicamente tu hogar.": "Use sounds of quartz bowls or Koshi chimes to acoustically purify your home.",
    "Mantén un espacio de lectura o meditación libre de dispositivos móviles para asegurar un santuario de paz.": "Keep a reading or meditation space free of mobile devices to ensure a sanctuary of peace.",
    "Prueba usar velas de cera de soja con aromas neutros o maderosos para dar calidez a tus momentos de introspección.": "Try using soy wax candles with neutral or woody scents to bring warmth to your moments of introspection.",
    "Asegura una postura cómoda y erguida en tu asiento habitual para propiciar el flujo libre de tu respiración.": "Ensure a comfortable and upright posture in your usual seat to promote the free flow of your breath.",

