    "Baja autoestima, desamor, fatiga vital y desconexión con el corazón.": "Low self-esteem, lack of love, vital fatigue, and disconnection with the heart.",
    "Conocida como la frecuencia de la transformación and los milagros. Resuena en el centro del pecho promoviendo la autocompasión, la fuerza vital y la claridad mental.": "Known as the frequency of transformation and miracles. It resonates in the center of the chest promoting self-compassion, vital force, and mental clarity.",
    "Soledad, resentimiento, desconfianza y aislamiento social o familiar.": "Loneliness, resentment, distrust, and social or family isolation.",
    "Fomenta la comunicación fluida, la empatía y la tolerancia en las relaciones humanas. Es excelente para superar tensiones interpersonales y sanar heridas por distancia.": "Fosters fluid communication, empathy, and tolerance in human relationships. It is excellent for overcoming interpersonal tensions and healing wounds caused by distance.",
    "Actúa como un purificador mental para disolver pensamientos repetitivos o tóxicos. Impulsa la libre expresión y el desarrollo de soluciones intuitivas.": "Acts as a mental purifier to dissolve repetitive or toxic thoughts. It boosts free expression and the development of intuitive solutions.",
    "Desorientación existencial, ilusión mental y desconexión con el ser espiritual.": "Existential disorientation, mental illusion, and disconnection with the spiritual self.",
    "Ayuda a elevar la conciencia individual abriendo la intuición profunda. Te asiste en ver la verdad del ser y recuperar la calma y balance a nivel espiritual.": "Helps raise individual consciousness by opening deep intuition. It assists you in seeing the truth of the self and recovering calm and balance on a spiritual level.",
    "Vacío emocional, separación existencial y olvido de la presencia interior.": "Emotional void, existential separation, and forgetting the inner presence.",
    "La 'frecuencia de la corona' despierta la conexión intrínseca con el universo y el estado puro del ser, uniendo cuerpo y mente en paz absoluta.": "The 'crown frequency' awakens the intrinsic connection with the universe and the pure state of being, uniting body and mind in absolute peace.",
