    "son:": "are:",
    "Esta lectura es una redacción propia de ¡Suelta!, inspirada en el enfoque simbólico de la biodescodificación. Si te interesa profundizar en este enfoque, estas son obras de referencia reconocidas en el tema:": "This reading is an original creation by ¡Suelta!, inspired by the symbolic approach of biodecoding. If you are interested in exploring this approach further, these are recognized reference works:",
    "Bienvenido a tu nuevo refugio": "Welcome to your new sanctuary",
    "Tu cuenta ha sido creada. Prepárate para iniciar un viaje de autoconocimiento. Aquí aprenderás a escuchar tus emociones sin juicios y a soltar lo que ya no te sirve.": "Your account has been created. Get ready to embark on a journey of self-knowledge. Here you will learn to listen to your emotions without judgment and let go of what no longer serves you.",
    "Profundiza en tu proceso": "Deepen your journey",
    "Puedes usar ¡Suelta! gratuitamente para dar tus primeros pasos. Nuestra suscripción Premium te ofrece análisis emocionales completos, acceso a todos los días del reto y un historial ilimitado de tu diario.": "You can use ¡Suelta! for free to take your first steps. Our Premium subscription offers complete emotional analyses, access to all days of the challenge, and unlimited journal history.",
    "Tu camino, a tu ritmo": "Your path, at your pace",
    "A continuación te mostraremos nuestros planes. Elige el que mejor te acompañe hoy; siempre podrás comenzar gratis y evolucionar cuando estés listo.": "Next, we will show you our plans. Choose the one that best supports you today; you can always start for free and upgrade when you're ready.",
    "Ver planes": "View plans",
    "Para garantizar tu máxima privacidad y blindaje de datos, LA ^ VACHE **no solicita, gestiona ni almacena** tus números de tarjeta de crédito. La compra se procesará de forma segura a través de la pasarela de pagos nativa del sistema operativo de tu dispositivo móvil.": "To guarantee your maximum privacy and data protection, LA ^ VACHE **does not request, manage, or store** your credit card numbers. The purchase will be processed securely via your mobile device operating system's native payment gateway.",
