    "Decodificador de Críticas y Empatía Profunda": "Criticism Decoder & Deep Empathy",
    "Aprende a escuchar el dolor del otro cuando te ataca, traduciendo sus reproches hostiles en necesidades insatisfechas para proteger tu paz.": "Hear the unspoken pain when someone attacks, translating hostility into unmet needs to protect your peace.",
