    "Trabajaremos con los 22 arcanos mayores, que trazan el llamado “Viaje del Loco”: un recorrido simbólico desde el primer paso lleno de fe hasta la plenitud. Cada carta es un arquetipo, un espejo de una etapa de la vida.": "We work with the 22 Major Arcana, tracing 'The Fool's Journey': a symbolic path from a leap of faith to wholeness. Each card is a mirror of life's stages.",
