    // Modal Guía Permisos Ajustes (EN)
    "Activar Permiso de Micrófono": "Enable Microphone Permission",
    "El micrófono te permite expresarte y dictar tus historias, diario emocional y reflexiones de voz sin tener que escribir a mano.": "The microphone allows you to express yourself and dictate stories, your emotional journal, and voice reflections without typing.",
    "Abre los Ajustes o Configuración de tu teléfono Android.": "Open Settings on your Android phone.",
    "Ve a la sección 'Aplicaciones' (o 'Administrador de aplicaciones').": "Go to the 'Apps' (or 'Application Manager') section.",
    "Busca y selecciona 'Suelta'.": "Find and select 'Suelta'.",
    "Toca en 'Permisos' (o 'Permisos de la app').": "Tap 'Permissions' (or 'App Permissions').",
    "Selecciona 'Micrófono' y cámbialo a 'Permitir solo mientras la app está en uso'.": "Select 'Microphone' and set it to 'Allow only while using the app'.",
    "Activar Permiso de Notificaciones": "Enable Notifications Permission",
    "Las notificaciones te envían tus recordatorios de calma, afirmaciones diarias y te avisan para continuar tu reto de 21 días.": "Notifications deliver calm reminders, daily affirmations, and nudge you to continue your 21-day challenge.",
    "Ve a 'Aplicaciones' y selecciona 'Suelta'.": "Go to 'Apps' and select 'Suelta'.",
    "Toca en la sección 'Notificaciones'.": "Tap the 'Notifications' section.",
    "Activa el interruptor 'Permitir todas las notificaciones de Suelta'.": "Turn on the switch 'Allow all notifications from Suelta'.",
    "Asegúrate de que no esté en modo 'Silencioso' o bloqueado por Ahorro de Batería.": "Make sure it is not in 'Silent' mode or blocked by Battery Saver.",
    "Activar Permiso de Cámara": "Enable Camera Permission",
    "La cámara te permite tomar tu foto de perfil de bienestar y registrar imágenes significativas en tu diario.": "The camera lets you capture your wellness profile picture and save meaningful images in your journal.",
    "Ve a 'Aplicaciones' > Busca 'Suelta'.": "Go to 'Apps' > Find 'Suelta'.",
    "Toca en 'Permisos'.": "Tap 'Permissions'.",
    "Selecciona 'Cámara' y cámbiala a 'Permitir solo mientras la app está en uso'.": "Select 'Camera' and set it to 'Allow only while using the app'.",
    "Habilitar Permisos de la App": "Enable App Permissions",
    "Para que Suelta funcione con todas sus herramientas, necesita los permisos de tu sistema Android.": "For Suelta to function with all its features, it requires permissions from your Android system.",
