    "Resonancia Somática (Vocal Humming)": "Somatic Resonance (Vocal Humming)",
    "Usa tu propia voz para sintonizar and masajear órganos y glándulas endocrinas al ritmo de tonos binaurales específicos.": "Use your own voice to tune and massage organs and endocrine glands to the rhythm of specific binaural tones.",
    "Armonización y Transmutación": "Harmonization & Transmutation",
    "Identifica un nudo o emoción activa y permite que la frecuencia recomendada sostenga tu ejercicio de escritura reflexiva y catarsis.": "Identify an active emotional knot and allow the recommended frequency to sustain your reflective journaling and catharsis.",
