    "Tocar para Silenciar": "Toucher pour couper le son",
    "Busca una posición cómoda, sentada o acostada, y cierra los ojos si te sientes segura.": "Trouvez une position confortable, assise ou allongée, et fermez les yeux si vous vous sentez en sécurité.",
    "Lleva tu atención a los pies. Nota su peso, su temperatura, sin cambiar nada, solo notando.": "Portez votre attention sur vos pieds. Remarquez leur poids, leur température, sans rien changer, en observant simplement.",
    "Sube la atención a las piernas y las caderas. Si hay tensión, no la fuerces a irse — solo reconócela.": "Montez votre attention vers vos jambes et vos hanches. S'il y a des tensions, ne les forcez pas à partir — reconnaissez-les simplement.",
    "Ahora el abdomen and el pecho. Sigue el ritmo natural de tu respiración, sin modificarlo.": "Maintenant l'abdomen et la poitrine. Suivez le rythme naturel de votre respiration, sans le modifier.",
    "Lleva la atención a los hombros. Es común que carguen tensión sin que te des cuenta — déjalos caer un poco.": "Portez votre attention sur vos épaules. Il est fréquent qu'elles portent des tensions sans que vous vous en rendiez compte — laissez-les tomber un peu.",
    "Por último, la cara y la cabeza. Suelta la mandíbula, suelta la frente.": "Enfin, le visage et la tête. Relâchez la mâchoire, détendez le front.",
    "Antes de abrir los ojos, nota cómo se siente todo tu cuerpo junto, de una vez.": "Avant d'ouvrir les yeux, remarquez ce que ressent tout votre corps réuni, d'un coup.",
