    "Este es un espacio para escucharte sin prisa. Elige una, dos o las tres opciones — cuanto más te permitas compartir, más clara será la luz que ilumine tu camino de vuelta a ti.": "C'est un espace pour s'écouter sans hâte. Choisissez une, deux ou trois options — plus vous vous permettez de partager, plus la lumière qui éclaire votre chemin de retour vers vous sera claire.",

    // Onboarding Slides
    "El espacio para soltar": "L'espace pour lâcher prise",
    "¡Suelta! es tu refugio digital. Te ayudamos a escuchar tus emociones, entender tus síntomas y reconectar con tu calma desde la raíz.": "Lâche prise ! est votre sanctuaire numérique. Nous vous accompagnons pour écouter vos ressentis, comprendre les messages du corps et retrouver votre paix intérieure.",
    "Exploración profunda": "Exploration profonde",
    "Obtén una lectura emocional de lo que sientes. Combinamos enfoques terapéuticos con perspectivas simbólicas para brindarte claridad.": "Obtenez un décodage émotionnel de ce que vous ressentez. Nous combinons des approches thérapeutiques et des perspectives symboliques pour vous apporter de la clarté.",
    "El Diálogo Humano": "Le Dialogue Humain",
    "Nada reemplaza el valor de conectar con otra persona. Te damos herramientas para transformar tus conversaciones en encuentros reales.": "Rien ne remplace la valeur d'une connexion humaine. Nous vous donnons des outils pour transformer vos conversations en rencontres réelles.",
    "Un viaje de 21 días": "Un voyage de 21 jours",
    "Acompáñanos en un reto guiado de 21 días. Lleva un diario de bienestar, forma nuevos hábitos y encuentra tu centro nuevamente.": "Rejoignez-nous pour un défi guidé de 21 jours. Tenez un journal de bien-être, adoptez de nouvelles habitudes et retrouvez votre centre.",

