    "Privacidad y datos (Habeas Data)": "Confidentialité et données",
    "Tu progreso e historial de bienestar se guardan de forma segura y cifrada en la nube bajo tu cuenta personal. En virtud de la Ley de Habeas Data, tienes el derecho de conocer, rectificar, actualizar o suprimir tu información en cualquier momento de manera irrevocable.": "Vos progrès et l'historique de votre bien-être sont sauvegardés en toute sécurité dans le cloud. Vous avez le droit d'accéder, de rectifier, de mettre à jour ou de supprimer vos informations à tout moment.",
