    "Sintomatología no encontrada": "Symptôme non trouvé",
    "No pudimos encontrar una decodificación exacta para tu búsqueda. Intenta buscar términos simples como 'cabeza', 'espalda', 'estómago' o 'ansiedad'.": "Nous n'avons pas trouvé de décodage émotionnel exact pour votre recherche. Essayez des termes simples comme 'tête', 'dos', 'estomac' ou 'anxiété'.",

    // 21-Day Challenge Practices
    "Escribe la frase exacta que te dices cuando aparece el malestar. Léela en voz alta y pregúntate si es del todo cierta.": "Écrivez la phrase exacte que vous vous dites lorsque le malaise survient. Lisez-la à haute voix et demandez-vous si elle est tout à fait vraie.",
    "Identifica en qué momento del día sientes más tensión. Solo obsérvalo, sin cambiar nada aún.": "Identifiez à quel moment de la journée vous ressentez le plus de tension. Observez-le simplement, sans rien changer pour l'instant.",
    "Recuerda la primera vez que sentiste algo parecido a lo que vives hoy. ¿Qué edad tenías?": "Rappelez-vous la première fois que vous avez ressenti quelque chose de similaire à ce que vous vivez aujourd'hui. Quel âge aviez-vous ?",
    "Hoy, cada vez que aparezca el malestar, respira hondo tres veces antes de reaccionar.": "Aujourd'hui, chaque fois que le malaise apparaît, prenez trois grandes respirations avant de réagir.",
    "Escribe una carta que no vas a enviar, dirigida a quien crees que está ligado a este conflicto.": "Écrivez une lettre que vous n'enverrez pas, adressée à la personne que vous pensez être liée à ce conflit.",
    "Nombra en voz alta lo que sientes, usando la frase: \u201cme permito sentir…\u201d.": "Nommez à haute voix ce que vous ressentez, en utilisant la phrase : \u201cje m'autorise à ressentir...\u201d.",
    "Haz una pausa de 5 minutos hoy solo para ti, sin pantallas ni tareas.": "Faites une pause de 5 minutes aujourd'hui rien que pour vous, sans écrans ni tâches.",
    "Observa tu cuerpo: ¿dónde se aloja la emoción? Ponle una mano encima un minuto.": "Observez votre corps : où se loge l'émotion ? Posez une main dessus pendant une minute.",
    "Escribe tres cosas que este malestar ha intentado protegerte o enseñarte.": "Écrivez trois choses que ce malaise a essayé de protéger ou de vous enseigner.",
    "Perdónate por algo pequeño de hoy. Dilo en voz alta.": "Pardonnez-vous pour quelque chose de petit aujourd'hui. Dites-le à haute voix.",
    "Reconoce a alguien de tu familia cuyo destino sientes que cargas. Solo míralo con respeto.": "Reconnaissez un membre de votre famille dont vous sentez porter le destin. Regardez-le simplement avec respect.",
    "Hoy di \u201cno\u201d a algo que normalmente aceptarías por costumbre.": "Aujourd'hui, dites \u201cnon\u201d à quelque chose que vous accepteriez normalement par habitude.",
    "Agradece a tu cuerpo por avisarte, en lugar de pelearte con el síntoma.": "Remerciez votre corps de vous avoir prévenu, au lieu de lutter contre le symptôme.",
    "Escribe cómo te gustaría sentirte dentro de un año, en presente.": "Écrivez comment vous aimeriez vous sentir dans un an, au présent.",
    "Suelta un objeto, una idea o una rutina que ya no te sirve.": "Lâchez un objet, une idée ou une routine qui ne vous sert plus.",
    "Dedica hoy a mirar lo que sí funciona en tu vida, por pequeño que sea.": "Consacrez aujourd'hui à regarder ce qui fonctionne dans votre vie, aussi petit soit-il.",
    "Repite tu frase de sanación mirándote al espejo.": "Répétez votre phrase de guérison en vous regardant dans le miroir.",
    "Haz las paces simbólicamente con una versión más joven de ti.": "Faites symboliquement la paix avec une version plus jeune de vous-même.",
    "Comparte con alguien de confianza una parte de este proceso.": "Partagez une partie de ce processus avec une personne de confiance.",
    "Escribe qué ha cambiado en ti desde el día 1, aunque sea sutil.": "Écrivez ce qui a changé en vous depuis le premier jour, même si c'est subtil.",
    "Celebra haber llegado hasta aquí. Escribe una promesa amable para tu futuro.": "Célébrez le fait d'être arrivé jusqu'ici. Écrivez une promesse bienveillante pour votre avenir.",

    // Motivational Messages
    "El primer paso siempre requiere valentía, {nombre}. ¿Comenzamos hoy?": "Le premier pas demande toujours du courage, {nombre}. Commençons-nous aujourd'hui ?",
    "Estás sembrando una hermosa semilla de consciencia, {nombre}. Sigue regándola día a día.": "Vous semez une belle graine de conscience, {nombre}. Continuez à l'arroser jour après jour.",
    "¡Gran constancia! Siente cómo cada práctica aporta ligereza a tu respiración.": "Grande régularité ! Ressentez comment chaque pratique apporte de la légèreté à votre respiration.",
    "Tu compromiso es un faro de amor propio. Ya has recorrido más de la mitad de tu viaje.": "Votre engagement est un phare d'amour de soi. Vous avez déjà parcouru plus de la moitié de votre voyage.",
    "La transformación florece en ti, {nombre}. Estás a muy pocos pasos de integrar este hábito sagrado.": "La transformation fleurit en vous, {nombre}. Vous êtes à quelques pas d'intégrer cette habitude sacrée.",
    "¡Felicidades, {nombre}! Has completado tus 21 días de conexión profunda. Un hito sagrado en tu sanación.": "Félicitations, {nombre} ! Vous avez accompli vos 21 jours de connexion profonde. Un jalon sacré dans votre guérison.",
