    "Este reporte se encuentra protegido y guardado en tu cuenta segura en la nube (respaldado por la infraestructura empresarial de Google Cloud). Se actualiza dinámicamente con cada re-cálculo.": "Ce rapport est protégé et enregistré dans votre compte cloud sécurisé (soutenu par l'infrastructure d'entreprise Google Cloud). Il se met à jour de façon dynamique à chaque re-calcul.",

