    // Recommendations Expresión
    "Dedica 5 minutos al inicio del día para escribir de forma libre (sin levantar la pluma del papel) para drenar la rumiación.": "Consacrez 5 minutes en début de journée à écrire librement (sans lever le stylo du papier) pour évacuer la rumination.",
    "Acompaña tus prácticas de diario con solfeo de 396Hz para disolver bloqueos y miedos inconscientes.": "Accompagnez vos pratiques de journal d'un solfège à 396Hz pour dissoudre les blocages et les peurs inconscientes.",
    "Practica la respiración de caja (inhalar 4, retener 4, exhalar 4, retener 4) antes de iniciar tus reflexiones.": "Pratiquez la respiration carrée (inspirer 4, retenir 4, expirer 4, retenir 4) avant de commencer vos réflexions.",
    "Utiliza la escritura como un espacio de compasión, permitiéndote llorar o plasmar tus penas sin culpas ni juicios.": "Utilisez l'écriture comme un espace de compassion, vous permettant de pleurer ou d'exprimer vos peines sans culpabilité ni jugement.",
    "Sintoniza la frecuencia de solfeo de 528Hz para promover la restauración celular de tu estado de ánimo y el amor propio.": "Accordez-vous à la fréquence de solfège 528Hz pour favoriser la restauration cellulaire de votre humeur et l'amour de soi.",
    "Agrega una sección fija al final de cada escrito donde menciones una sola cosa por la que sientas aprecio sincero hoy.": "Ajoutez une section fixe à la fin de chaque écrit où vous mentionnez une seule chose pour laquelle vous ressentez une appréciation sincère aujourd'hui.",
    "Escribe sobre tu enojo de forma explícita, arrugando o rompiendo el papel después (si es físico) para dar salida física a la emoción.": "Écrivez explicitement sur votre colère, puis froissez ou déchirez le papier (s'il est physique) pour donner un exutoire physique à l'émotion.",
    "Usa solfeo de 417Hz para sintonizar con la limpieza de energías estancadas y facilitar la aceptación del cambio.": "Utilisez le solfège 417Hz pour vous accorder au nettoyage des énergies stagnantes et faciliter l'acceptation du changement.",
    "Introduce pausas conscientes de silencio absoluto de 1 minuto antes de responder a situaciones tensas.": "Introduisez des pauses conscientes de silence absolu d'une minute avant de répondre à des situations tendues.",
    "¡Excelente balance! Expande tu bienestar describiendo a detalle los rostros, olores y sensaciones de los momentos felices.": "Excellent équilibre ! Développez votre bien-être en décrivant en détail les visages, les odeurs et les sensations des moments heureux.",
    "Sintoniza frecuencias de 639Hz y 852Hz para elevar tu intuición y fortalecer tus conexiones interpersonales.": "Accordez-vous aux fréquences 639Hz et 852Hz pour élever votre intuition et renforcer vos connexions interpersonnelles.",
    "Comparte un pensamiento de gratitud con alguien de tu entorno para contagiar y amplificar tu bienestar.": "Partagez une pensée de gratitude avec quelqu'un de votre entourage pour propager et amplifier votre bien-être.",
    "Mantén la constancia en tu registro diario. La regularidad es la clave para la auto-consciencia.": "Restez régulier dans la tenue de votre journal quotidien. La régularité est la clé de la conscience de soi.",
    "Prueba variar los temas de tu diario alternando entre relatos de tu día y descripciones puramente emocionales o corporales.": "Essayez de varier les thèmes de votre journal, en alternant entre les récits de votre journée et des descriptions purement émotionnelles ou corporelles.",
    "Usa solfeo de 432Hz o 528Hz de fondo para sintonizar con los armónicos naturales del entorno.": "Utilisez le solfège 432Hz ou 528Hz en arrière-plan pour vous accorder aux harmoniques naturelles de l'environnement.",

    // Recommendations Entorno
    "Crea una rutina de desconexión digital absoluta al menos 45 minutos antes de dormir.": "Créez une routine de déconnexion numérique absolue au moins 45 minutes avant de dormir.",
    "Introduce difusores con esencia de lavanda, bergamota o manzanilla en tu espacio de descanso.": "Introduisez des diffuseurs à l'essence de lavande, de bergamote ou de camomille dans votre espace de repos.",
    "Mantén luces cálidas y tenues por la noche para indicarle a tu sistema nervioso que está seguro.": "Gardez des lumières chaudes et tamisées la nuit pour signaler à votre système nerveux qu'il est en sécurité.",
    "Busca activamente el contacto con la luz natural durante las mañanas (camina al menos 10 minutos bajo el sol).": "Recherchez activement le contact avec la lumière naturelle le matin (marchez au moins 10 minutes sous le soleil).",
    "Introduce plantas de interior 🌱 o flores frescas en tu espacio vital para renovar el aire y la energía visual.": "Introduisez des plantes d'intérieur 🌱 ou des fleurs fraîches dans votre espace de vie pour renouveler l'air et l'énergie visuelle.",
    "Escucha sonidos de agua corriente (lluvia, fuentes) de fondo para facilitar el flujo emocional.": "Écoutez des bruits d'eau courante (pluie, fontaines) en arrière-plan pour faciliter le flux émotionnel.",
    "Asegura el orden visual en tu mesa o escritorio, ya que el desorden físico incrementa la reactividad mental.": "Veillez à l'ordre visuel sur votre table ou bureau, car le désordre physique augmente la réactivité mentale.",
    "Crea un 'rincón de descarga': un lugar cómodo con cojines donde puedas respirar o descansar sin ruidos molestos.": "Créez un 'coin de libération' : un endroit confortable avec des coussins où vous pourrez respirer ou vous reposer sans bruits gênants.",
    "Aromatiza tu espacio con esencias cítricas (limón, naranja) para elevar la claridad mental y refrescar la atmósfera.": "Parfumez votre espace avec des essences d'agrumes (citron, orange) pour élever la clarté mentale et rafraîchir l'atmosphère.",
    "Conserva fotos de momentos alegres, seres queridos o frases inspiradoras a la vista en tu habitación.": "Conservez des photos de moments heureux, d'êtres chers ou de phrases inspirantes à portée de vue dans votre chambre.",
    "Ventila tus espacios habitacionales diariamente para permitir la renovación constante de la energía vital.": "Aérez quotidiennement vos espaces de vie pour permettre le renouvellement constant de l'énergie vitale.",
    "Utiliza sonidos de cuencos de cuarzo o campanas koshi para purificar acústicamente tu hogar.": "Utilisez des sons de bols de quartz ou de carillons koshi pour purifier acoustiquement votre maison.",
    "Mantén un espacio de lectura o meditación libre de dispositivos móviles para asegurar un santuario de paz.": "Gardez un espace de lecture ou de méditation sans appareils mobiles pour assurer un sanctuaire de paix.",
    "Prueba usar velas de cera de soja con aromas neutros o maderosos para dar calidez a tus momentos de introspección.": "Essayez d'utiliser des bougies en cire de soja aux parfums neutres ou boisés pour réchauffer vos moments d'introspection.",
    "Asegura una postura cómoda y erguida en tu asiento habitual para propiciar el flujo libre de tu respiración.": "Veillez à une posture confortable et droite sur votre siège habituel pour favoriser la libre circulation de votre respiration.",

