    "Inhala por 4s, sostén por 4s, exhala por 4s...": "Inspirer pendant 4s, retenir pendant 4s, expirer pendant 4s...",
    "1. Ve a tu pantalla de inicio de iOS, mantén presionada una zona vacía o un ícono hasta que todas las apps comiencen a vibrar.": "1. Allez sur votre écran d'accueil iOS, maintenez enfoncée une zone vide ou une icône jusqu'à ce que les applications commencent à trembler.",
    "2. Presiona el botón \"+\" en la esquina superior izquierda.": "2. Appuyez sur le bouton \"+\" dans le coin supérieur gauche.",
    "3. Busca y selecciona la aplicación instalada \"¡Suelta!\" de la lista de widgets.": "3. Recherchez et sélectionnez l'application installée \"Lâche prise !\" dans la liste des widgets.",
    "4. Elige el tamaño que prefieras (Chico o Mediano) y toca en \"Añadir widget\". ¡Listo!": "4. Choisissez la taille préférée (Petit ou Moyen) et appuyez sur \"Ajouter le widget\". C'est prêt !",
    "1. Mantén presionado cualquier espacio vacío en la pantalla de inicio de tu celular Android.": "1. Maintenez enfoncé n'importe quel espace vide sur l'écran d'accueil de votre téléphone Android.",
    "2. Toca la opción Widgets que aparece en el menú inferior.": "2. Appuyez sur l'option Widgets qui apparaît dans le menu inférieur.",
    "3. Desplázate hasta encontrar la aplicación instalada \"¡Suelta!\".": "3. Faites défiler jusqu'à trouver l'application installée \"Lâche prise !\".",
    "4. Mantén presionado el widget elegido, arrástralo hasta la posición que prefieras en tu pantalla principal y suéltalo. ¡Listo!": "4. Maintenez enfoncé le widget choisi, faites-le glisser vers la position de votre choix sur votre écran d'accueil et relâchez-le. C'est prêt !",
    "Te enviaremos breves notificaciones constantes durante el día para reconectar con tu esencia, motivarte y respirar.": "Nous vous enverrons de brèves notifications constantes au cours de la journée pour vous reconnecter avec votre essence, vous motiver et respirer.",
    "Enviaremos un correo para guiar tu práctica diaria de transformación.": "Nous enverrons un e-mail pour guider votre pratique quotidienne de transformation.",
    "🦉 Presencia Consciente": "🦉 Présence consciente",
    "Hola viajero, detén tus pensamientos por 5 segundos. Siente tu respiración y baja los hombros.": "Bonjour voyageur, arrêtez vos pensées pendant 5 secondes. Santez votre respiration et baissez vos épaules.",
    "✨ La Esencia de Hoy": "✨ L'essence d'aujourd'hui",
    "Recuerda tu reto de hoy: \"{practica}\". Todo fluye cuando dejas de resistir.": "Rappelez-vous votre défi aujourd'hui : \"{practica}\". Tout s'écoule quand vous arrêtez de résister.",
    "🌿 ¡Suelta!": "🌿 Lâche prise !",
    "Estás sanando a tu propio ritmo, y cada pequeño paso cuenta. Sigue adelante.": "Vous guérissez à votre propre rythme, et chaque petit pas compte. Continuez.",
    "💫 Pausa del Alma": "💫 Pause de l'âme",
    "Inhala paz, exhala tensión. Tu cuerpo y tu mente te agradecen este espacio de conexión.": "Inspirez la paix, expirez la tension. Votre corps et votre esprit vous remercient pour cet espace de connexion.",
    "🌟 Un recordatorio cariñoso": "🌟 Un rappel affectueux",
    "Tu valor no se mide por lo que haces, sino por el amor y la presencia que eres aquí y ahora.": "Votre valeur ne se mesure pas à ce que vous faites, mais à l'amour et à la présence que vous êtes ici et maintenant.",
    "Comparte contigo": "Partager avec soi-même",
    "Escuchando": "Écoute en cours",
    "¿Prefieres que te guiemos?": "Préfères-tu qu'on te guide ?",
    "Recorre tu vida en tres etapas (infancia, adolescencia, adultez) para desbloquear memorias.": "Parcours ta vie en trois étapes (enfance, adolescence, âge adulte) pour débloquer des souvenirs.",
    "Escribe tu historia aquí... no te preocupes por el formato, solo déjalo salir, o toca el micrófono para contarla en voz alta.": "Écris ton histoire ici... ne t'inquiète pas du format, laisse simplement couler, ou appuie sur le micro pour la raconter à voix haute.",
    "El dictado por voz no está disponible en este navegador — puedes escribir directamente.": "La dictée vocale n'est pas disponible sur ce navigateur — vous pouvez écrire directement.",
    "Algoritmo de Análisis de 21 Días": "Algorithme d'analyse de 21 jours",
    "Análisis personalizado de patrones de escritura y salud emocional": "Analyse personnalisée des schémas d'écriture et de la santé émotionnelle",
    "Nuestro algoritmo de bienestar analiza la profundidad de tus reflexiones, el volumen de palabras y las frecuencias semánticas emocionales de tus registros para ofrecerte un diagnóstico interactivo y recomendaciones a la medida para tu hogar, trabajo y expresión.": "Notre algorithme de bien-être analyse la profondeur de vos réflexions, le volume de mots et les fréquences sémantiques émotionnelles de vos écrits pour vous proposer un diagnostic interactif et des recommandations sur mesure pour votre foyer, votre travail et votre expression.",
    "Ejecutar Algoritmo de Análisis": "Exécuter l'algorithme d'analyse",
    "Procesando patrones...": "Traitement des schémas...",
    "Re-calcular Análisis": "Recalculer l'analyse",
    "Emoción Dominante": "Émotion dominante",
    "Estilo de Escritura": "Style d'écriture",
    "Frecuencias de Palabras Detectadas": "Fréquences des mots détectés",
