    "Tristeza / Procesamiento": "Tristesse / Traitement",
    "Gratitud / Florecimiento": "Gratitude / Épanouissement",
    "Frustración / Tensión": "Frustration / Tension",
    "Total de palabras analizadas:": "Total des mots analysés :",
    "Tu profundidad de escritura sugiere un alto nivel de desahogo y conexión consigo mismo.": "La profondeur de votre écriture suggère un niveau élevé de soulagement et de connexion avec vous-même.",
    "Tu profundidad de escritura sugiere un enfoque puntual y reflexivo.": "La profondeur de votre écriture suggère une approche ciblée et réflexive.",
    "Recomendaciones de Expresión Emocional": "Recommandations d'expression émotionnelle",
    "Recomendaciones para tu Entorno Personal": "Recommandations pour votre environnement personnel",
    "Este reporte se encuentra protegido y guardado en tu cuenta segura en la nube (respaldado por la infraestructura empresarial de Google Cloud). Se actualiza dinámicamente con cada re-cálculo.": "Ce rapport est protégé et enregistré sur votre compte cloud sécurisé (sauvegardé par l'infrastructure d'entreprise Google Cloud). Il se met à jour dynamiquement à chaque recalcul.",
    "Presiona el botón de arriba para que el algoritmo procese tus reflexiones diarias y te ofrezca un diagnóstico semántico detallado.": "Appuyez sur le bouton ci-dessus pour que l'algorithme traite vos réflexions quotidiennes et vous propose un diagnostic sémantique détaillé.",
    "Infancia": "Enfance",
    "¿Qué recuerdas de tu infancia? Un momento, un olor, una escena, una emoción que aún vive en ti.": "Que vous rappelez-vous de votre enfance ? Un moment, une odeur, une scène, une émotion qui vit encore en vous.",
    "No hay respuesta correcta. Lo que venga primero suele ser lo más honesto.": "Il n'y a pas de bonne réponse. Ce qui vient en premier est généralement le plus honnête.",
    "Adolescencia": "Adolescence",
    "¿Qué marcó tu adolescencia? Algo que aprendiste, algo que dolió, algo que aún cargas.": "Qu'est-ce qui a marqué votre adolescence ? Quelque chose que vous avez appris, quelque chose qui a fait mal, quelque chose que vous portez encore.",
    "Piensa en un momento que hoy, mirándolo, todavía te mueve algo por dentro.": "Pensez à un moment qui aujourd'hui, en le regardant, éveille encore quelque chose en vous.",
    "Adultez": "Âge adulte",
    "¿Cómo llegaste a ser quien eres hoy? Qué has soltado, qué te falta soltar.": "Comment êtes-vous devenu la personne que vous êtes aujourd'hui ? Qu'avez-vous lâché prise, qu'est-ce qu'il vous reste à lâcher ?",
    "Puedes hablar del presente, de lo reciente, o de aquello que sigue pendiente contigo.": "Vous pouvez parler du présent, du récent ou de ce qui reste en suspens avec vous-même.",
