    "¿Qué hay en tu corazón hoy? Tómate tu tiempo, descárgate libremente sin juicios...": "Qu'y a-t-il dans votre cœur aujourd'hui ? Prenez votre temps, libérez-vous sans jugement...",
    "Escuchando… habla con libertad y vuelve a pulsar el micrófono para pausar.": "Écoute en cours… parlez librement et appuyez à nouveau sur le micro pour mettre en pause.",
