    "Limpiar filtros": "Effacer les filtres",
    "Gracias por escribirlo. Para afinar tu lectura, respóndenos dos cosas más. Son opcionales, pero ayudan a que la orientación sea más precisa.": "Merci de l'avoir écrit. Pour affiner l'analyse, répondez à deux autres questions. Elles sont facultatives, mais aident à rendre les conseils plus précis.",
