    // New translations for Somatic Captures, Body Map, and Solfeggio
    "Elige la zona del cuerpo donde presentas tu afectación": "Choisissez la zone du corps où vous présentez votre affection",
    "Selecciona un punto de tensión o dolor directamente sobre la silueta corporal.": "Sélectionnez un point de tension ou de douleur directement sur la silhouette corporelle.",
    "Sabiduría Somática": "Sagesse Somatique",
    "O detállalo con tus propias palabras a continuación:": "Ou détaillez-le avec vos propres mots ci-dessous :",
