    "Analizar mi información": "Analyser mes informations",
    "Escuchando lo que tu cuerpo tiene para decir": "À l'écoute de ce que votre corps a à dire",
    "Buscando el hilo entre lo que sientes y lo que tu cuerpo recuerda": "À la recherche du lien entre ce que vous ressentez et ce dont votre corps se souvient",
    "Elige tu plan": "Choisissez votre forfait",
    "Experiencia Horizontal Recomendada": "Expérience Horizontale Recommandée",
    "Para navegar por el mapa de tu cuerpo y explorar la sabiduría somática con total claridad y movimiento, gira tu dispositivo horizontalmente.": "Pour naviguer sur la carte de votre corps et explorer la sagesse somatique avec clarté et mouvement, tournez votre appareil horizontalement.",
    "Entendido, continuar en vertical": "Compris, continuer en vertical",
    "Energía Femenina": "Énergie Féminine",
    "Energía Masculina": "Énergie Masculine",
    "Prácticas de Solfeo": "Pratiques du Solfège",
    "Integra el poder sanador de las frecuencias Solfeggio con ejercicios prácticos diseñados para movilizar tu energía somática y transmutar bloqueos emocionales.": "Intégrez le pouvoir guérisseur des fréquences Solfeggio avec des exercices pratiques conçus pour mobiliser votre énergie somatique et transmuter les blocages émotionnels.",
    "Resonancia Somática (Vocal Humming)": "Résonance Somatique (Vocal Humming)",
    "Usa tu propia voz para sintonizar and masajear órganos y glándulas endocrinas al ritmo de tonos binaurales específicos.": "Utilisez votre propre voix pour accorder et masser les organes et les glandes endocrines au rythme de tons binauraux spécifiques.",
    "Armonización y Transmutación": "Harmonisation et Transmutation",
    "Identifica un nudo o emoción activa y permite que la frecuencia recomendada sostenga tu ejercicio de escritura reflexiva y catarsis.": "Identifiez un nœud ou une émotion active et permettez à la fréquence recommandée de soutenir votre exercice d'écriture réflexive et de catharsis.",
    "Calibrador Sensorial": "Calibreur Sensoriel",
    "Explora con total libertad los 7 tonos de bienestar, lee sus perfiles somáticos and siente dónde resuena cada vibración en tu cuerpo.": "Explorez en toute liberté les 7 tons de bien-être, lisez leurs profils somatiques et ressentez où résonne chaque vibration dans votre corps.",
    "Explora con total libertad los 7 tonos de bienestar, lee sus perfiles somáticos y siente dónde resuena cada vibración en tu cuerpo.": "Explorez en toute liberté les 7 tons de bien-être, lisez leurs profils somatiques et ressentez où résonne chaque vibration dans votre corps.",
