    "Resistencia mental, control, sobrepensamiento o cansancio intelectual.": "Résistance mentale, contrôle, surmenage ou fatigue intellectuelle.",
    "¿Qué situación estás intentando analizar o controlar con demasiada fuerza?": "Quelle situation essayez-vous d'analyser ou de contrôler trop fortement ?",
    "Palabras silenciadas, expresión contenida, dificultad para comunicar tu verdad.": "Mots réduits au silence, expression contenue, difficulté à communiquer votre vérité.",
    "¿Qué emoción o verdad no te estás permitiendo decir en voz alta?": "Quelle émotion ou vérité ne vous permettez-vous pas de dire à haute voix ?",
    "Cierre emocional, miedo a ser herido, duelos afectivos o tristezas guardadas.": "Fermeture émotionnelle, peur d'être blessé, deuil affectif ou tristesse contenue.",
    "¿De qué dolor del pasado estás intentando proteger tu sensibilidad?": "De quelle douleur du passé essayez-vous de protéger votre sensibilité ?",
    "Carga de angustia, opresión existencial, falta de espacio vital para ser.": "Fardeau d'angoisse, oppression existentielle, manque d'espace vital pour être.",
    "¿Qué pena o angustia está pesando sobre tu pecho limitando tu respiración?": "Quelle peine ou angoisse pèse sur votre poitrine, limitant votre respiration ?",
    "Mochilas del pasado, exceso de responsabilidades, falta de apoyo emocional.": "Sacs à dos du passé, excès de responsabilités, manque de soutien émotionnel.",
    "¿Qué cargas ajenas o culpas estás llevando sobre tus hombros?": "Quels fardeaux d'autrui ou culpabilités portez-vous sur vos épaules ?",
    "Realidades difíciles de asimilar, rabia o impotencia 'indigesta'.": "Réalités difficiles à assimiler, colère ou impuissance 'indigeste'.",
    "¿Qué situación o cambio reciente te está costando tanto 'digerir'?": "Quelle situation ou changement récent avez-vous tant de mal à 'digérer' ?",
    "Control profundo de las emociones viscerales, miedos creativos o sexuales.": "Contrôle profond des émotions viscérales, peurs créatives ou sexuelles.",
    "¿Qué miedos profundos o impulsos creativos estás intentando contener?": "Quelles peurs profondes ou impulsions créatrices essayez-vous de contenir ?",
    "Incertidumbre ante los pasos futuros, miedo a avanzar, falta de estabilidad.": "Incertitude face aux pas futurs, peur d'avancer, manque de stabilité.",
    "¿Hacia qué dirección de tu vida tienes miedo o dudas de avanzar?": "Vers quelle direction de votre vie avez-vous peur ou hésitez-vous à avancer ?",
    "Miedo o Culpa": "Peur ou Culpabilité",
    "¿De qué carga o expectativa te gustaría liberarte hoy con la ayuda de este tono?": "De quel fardeau ou de quelle attente aimeriez-vous vous libérer aujourd'hui à l'aide de cette tonalité ?",
    "Frecuencia recomendada: 396 Hz (Liberación)": "Fréquence recommandée : 396 Hz (Libération)",
    "Estancamiento o Resistencia": "Stagnation ou Résistance",
    "¿Qué situación o hábito del pasado sientes que es hora de soltar y transformar?": "Quelle situation ou habitude du passé sentez-vous qu'il est temps de lâcher et de transformer ?",
