    "Desorientación o Confusión": "Désorientation ou Confusion",
    "Si tu intuición más profunda pudiera hablarte ahora mismo, ¿qué respuesta te daría sobre tu situación actual?": "Si votre intuition la plus profonde pouvait vous parler en ce moment même, quelle réponse vous donnerait-elle sur votre situation actuelle ?",
