    "¿Cómo practicar?": "Comment pratiquer ?",
    "Durante la exhalación, emite un tono suave imitando el sonido que escuchas. Trata de sentir cómo la vibración física de tu propia voz reverbera específicamente en la zona corporal señalada.": "Pendant l'expiration, émettez un ton doux en imitant le son que vous entendez. Essayez de ressentir comment la vibration physique de votre propre voix résonne spécifiquement dans la zone corporelle indiquée.",
