    "Baja autoestima, desamor, fatiga vital y desconexión con el corazón.": "Faible estime de soi, manque d'amour, fatigue vitale et déconnexion avec le cœur.",
    "Conocida como la frecuencia de la transformación and los milagros. Resuena en el centro del pecho promoviendo la autocompasión, la fuerza vital y la claridad mental.": "Connue comme la fréquence de la transformation et des miracles. Elle résonne au centre de la poitrine en favorisant l'auto-compassion, la force vitale et la clarté mentale.",
    "Soledad, resentimiento, desconfianza y aislamiento social o familiar.": "Solitude, ressentiment, méfiance et isolement social ou familial.",
    "Fomenta la comunicación fluida, la empatía y la tolerancia en las relaciones humanas. Es excelente para superar tensiones interpersonales y sanar heridas por distancia.": "Favorise une communication fluide, l'empathie et la tolérance dans les relations humaines. Elle est excellente pour surmonter les tensions interpersonnelles et guérir les blessures dues à la distance.",
    "Actúa como un purificador mental para disolver pensamientos repetitivos o tóxicos. Impulsa la libre expresión y el desarrollo de solutions intuitivas.": "Agit comme un purificateur mental pour dissoudre les pensées répétitives ou toxiques. Elle encourage la libre expression et le développement de solutions intuitives.",
    "Actúa como un purificador mental para disolver pensamientos repetitivos o tóxicos. Impulsa la libre expresión y el desarrollo de soluciones intuitivas.": "Agit comme un purificateur mental pour dissoudre les pensées répétitives ou toxiques. Elle encourage la libre expression et le développement de solutions intuitives.",
    "Desorientación existencial, ilusión mental y desconexión con el ser espiritual.": "Désorientation existentielle, illusion mentale et déconnexion avec l'être spirituel.",
    "Ayuda a elevar la conciencia individual abriendo la intuición profunda. Te asiste en ver la verdad del ser y recuperar la calma y balance a nivel espiritual.": "Aide à élever la conscience individuelle en ouvrant l'intuition profonde. Elle vous aide à voir la vérité de l'être et à retrouver le calme et l'équilibre sur le plan spirituel.",
    "Vacío emocional, separación existencial y olvido de la presencia interior.": "Vide émotionnel, séparation existentielle et oubli de la présence intérieure.",
    "La 'frecuencia de la corona' despierta la conexión intrínseca con el universo y el estado puro del ser, uniendo cuerpo y mente en paz absoluta.": "La 'fréquence de la couronne' éveille la connexion intrinsèque avec l'univers et l'état pur de l'être, unissant le corps et l'esprit dans une paix absolue.",
