    "son:": "sont :",
    "Esta lectura es una redacción propia de ¡Suelta!, inspirada en el enfoque simbólico de la biodescodificación. Si te interesa profundizar en este enfoque, estas son obras de referencia reconocidas en el tema:": "Cette lecture est une rédaction originale de Lâche prise !, inspirée de l'approche symbolique du décodage biologique. Si vous souhaitez approfondir cette approche, voici des ouvrages de référence reconnus :",
    "Bienvenido a tu nuevo refugio": "Bienvenue dans votre nouveau refuge",
    "Tu cuenta ha sido creada. Prepárate para iniciar un viaje de autoconocimiento. Aquí aprenderás a escuchar tus emociones sin juicios y a soltar lo que ya no te sirve.": "Votre compte a été créé. Préparez-vous à entamer un voyage de connaissance de soi. Ici, vous apprendrez à écouter vos émotions sans jugement et à lâcher prise.",
    "Profundiza en tu proceso": "Approfondissez votre processus",
    "Puedes usar ¡Suelta! gratuitamente para dar tus primeros pasos. Nuestra suscripción Premium te ofrece análisis emocionales completos, acceso a todos los días del reto y un historial ilimitado de tu diario.": "Vous pouvez utiliser Lâche prise ! gratuitement pour faire vos premiers pas. Notre abonnement Premium vous offre des analyses émotionnelles complètes, l'accès à tous les jours du défi et un historique illimité de votre journal.",
    "Tu camino, a tu ritmo": "Votre chemin, à votre rythme",
    "A continuación te mostraremos nuestros planes. Elige el que mejor te acompañe hoy; siempre podrás comenzar gratis y evolucionar cuando estés listo.": "Nous allons maintenant vous présenter nos formules. Choisissez celle qui vous convient le mieux aujourd'hui ; vous pouvez toujours commencer gratuitement.",
    "Ver planes": "Voir les forfaits",
    "Para garantizar tu máxima privacidad y blindaje de datos, LA ^ VACHE **no solicita, gestiona ni almacena** tus números de tarjeta de crédito. La compra se procesará de forma segura a través de la pasarela de pagos nativa del sistema operativo de tu dispositivo móvil.": "Pour garantir votre confidentialité maximale et la protection de vos données, LA ^ VACHE **ne demande, ne gère ni ne stocke** vos numéros de carte de crédit. L'achat sera traité en toute sécurité via la passerelle de paiement native de votre appareil mobile.",
