    "Activar Permiso de Micrófono": "Activer l'Autorisation du Microphone",
    "El micrófono te permite expresarte y dictar tus historias, diario emocional y reflexiones de voz sin tener que escribir a mano.": "Le microphone vous permet de vous exprimer et de dicter vos récits, votre journal émotionnel et vos réflexions vocales sans taper.",
    "Abre los Ajustes o Configuración de tu teléfono Android.": "Ouvrez les Paramètres de votre téléphone Android.",
    "Ve a la sección 'Aplicaciones' (o 'Administrador de aplicaciones').": "Allez dans la section « Applications » (ou « Gestionnaire d'applications »).",
    "Busca y selecciona 'Suelta'.": "Recherchez et sélectionnez « Suelta ».",
    "Toca en 'Permisos' (o 'Permisos de la app').": "Appuyez sur « Autorisations » (ou « Permissions de l'application »).",
