    "Activar Permiso de Notificaciones": "Activer l'Autorisation des Notifications",
    "Las notificaciones te envían tus recordatorios de calma, afirmaciones diarias y te avisan para continuar tu reto de 21 días.": "Les notifications envoient vos rappels de sérénité, vos affirmations quotidiennes et vous invitent à poursuivre le défi 21 jours.",
    "Ve a 'Aplicaciones' y selecciona 'Suelta'.": "Allez dans « Applications » et sélectionnez « Suelta ».",
