    "Asegúrate de que no esté en modo 'Silencioso' o bloqueado por Ahorro de Batería.": "Assurez-vous qu'il n'est pas en mode « Silencieux » ou restreint par l'Économiseur de batterie.",
    "Activar Permiso de Cámara": "Activer l'Autorisation de l'Appareil Photo",
    "La cámara te permite tomar tu foto de perfil de bienestar y registrar imágenes significativas en tu diario.": "L'appareil photo vous permet de prendre votre photo de profil et de conserver des images inspirantes dans votre journal.",
