    "Este es un espacio para escucharte sin prisa. A través de este recorrido guiado conectaremos tu historia, tu cuerpo y tus emociones paso a paso:": "Cet espace est conçu pour vous écouter avec bienveillance. À travers ce parcours guidé, nous relierons pas à pas votre vécu, votre corps et vos émotions :",
