    "Tocar para Silenciar": "Tocca per silenziare",
    "Busca una posición cómoda, sentada o acostada, y cierra los ojos si te sientes segura.": "Trova una posizione comoda, seduta o sdraiata, e chiudi gli occhi se ti senti al sicuro.",
    "Lleva tu atención a los pies. Nota su peso, su temperatura, sin cambiar nada, solo notando.": "Porta la tua attenzione ai piedi. Nota il loro peso, la loro temperatura, senza cambiare nulla, solo osservando.",
    "Sube la atención a las piernas y las caderas. Si hay tensión, no la fuerces a irse — solo reconócela.": "Sposta l'attenzione sulle gambe e sui fianchi. Se c'è tensione, non forzarla ad andarsene — semplicemente riconoscila.",
    "Ahora el abdomen and el pecho. Sigue el ritmo natural de tu respiración, sin modificarlo.": "Ora l'addome e il petto. Segui il ritmo naturale del tuo respiro, senza modificarlo.",
    "Lleva la atención a los hombros. Es común que carguen tensión sin que te des cuenta — déjalos caer un poco.": "Porta l'attenzione alle spalle. È comune che accumulino tensione senza che te ne accorga — lasciale cadere un po'.",
    "Por último, la cara y la cabeza. Suelta la mandíbula, suelta la frente.": "Infine, il viso e la testa. Rilascia la mandibola, distendi la fronte.",
    "Antes de abrir los ojos, nota cómo se siente todo tu cuerpo junto, de una vez.": "Prima di aprire gli occhi, nota come si sente tutto il tuo corpo insieme, in una volta sola.",
