    "Privacidad y datos (Habeas Data)": "Privacy e dati personali",
    "Tu progreso e historial de bienestar se guardan de forma segura y cifrada en la nube bajo tu cuenta personal. En virtud de la Ley de Habeas Data, tienes el derecho de conocer, rectificar, actualizar o suprimir tu información en cualquier momento de manera irrevocable.": "I tuoi progressi e la cronologia del tuo benessere sono salvati in modo sicuro e crittografato nel cloud sotto il tuo account personale. Hai il diritto di accedere, rettificare, aggiornare o cancellare i tuoi dati in qualsiasi momento in modo irrevocabile.",
