    "No pudimos encontrar una decodificación exacta para tu búsqueda. Intenta buscar términos simples como 'cabeza', 'espalda', 'estómago' o 'ansiedad'.": "Non abbiamo trovato una decodifica emotiva esatta per la tua ricerca. Prova con termini semplici come 'mal di testa', 'schiena', 'stomaco' o 'ansia'.",

    // 21-Day Challenge Practices
    "Escribe la frase exacta que te dices cuando aparece el malestar. Léela en voz alta y pregúntate si es del todo cierta.": "Scrivi la frase esatta che dici a te stesso quando sorge il disagio. Leggila ad voce e chiediti se è del tutto vera.",
    "Identifica en qué momento del día sientes más tensión. Solo obsérvalo, sin cambiar nada aún.": "Identifica in quale momento della giornata provi più tensione. Osservala e basta, senza cambiare nulla per ora.",
    "Recuerda la primera vez que sentiste algo parecido a lo que vives hoy. ¿Qué edad tenías?": "Ricorda la prima volta che hai provato qualcosa di simile a quello che stai vivendo oggi. Quanti anni avevi?",
    "Hoy, cada vez que aparezca el malestar, respira hondo tres veces antes de reaccionar.": "Oggi, ogni volta che compare il disagio, fai tre respiri profondi prima di reagire.",
    "Escribe una carta que no vas a enviar, dirigida a quien crees que está ligado a este conflicto.": "Scrivi una lettera che non spedirai, indirizzata a chi credi sia legato a questo conflitto.",
    "Nombra en voz alta lo que sientes, usando la frase: \u201cme permito sentir…\u201d.": "Nomina ad alta voce ciò que provi, usando la frase: \u201cmi permetto di sentire...\u201d.",
    "Haz una pausa de 5 minutos hoy solo para ti, sin pantallas ni tareas.": "Fai una pausa di 5 minuti oggi solo per te, senza schermi o compiti.",
    "Observa tu cuerpo: ¿dónde se aloja la emoción? Ponle una mano encima un minuto.": "Osserva il tuo corpo: dove si alloggia l'emozione? Appoggiaci sopra una mano per un minuto.",
    "Escribe tres cosas que este malestar ha intentado protegerte o enseñarte.": "Scrivi tre cose che questo disagio ha cercato di proteggere o insegnarti.",
    "Perdónate por algo pequeño de hoy. Dilo en voz alta.": "Perdonati per qualcosa di piccolo oggi. Dillo ad alta voce.",
    "Reconoce a alguien de tu familia cuyo destino sientes que cargas. Solo míralo con respeto.": "Riconosci qualcuno nella tua famiglia il cui destino senti di caricare. Guardalo solo con rispetto.",
    "Hoy di \u201cno\u201d a algo que normalmente aceptarías por costumbre.": "Oggi di' \u201cno\u201d a qualcosa che normalmente accetteresti per abitudine.",
    "Agradece a tu cuerpo por avisarte, en lugar de pelearte con el síntoma.": "Ringrazia il tuo corpo per averti avvisato, invece di combattere con il sintomo.",
    "Escribe cómo te gustaría sentirte dentro de un año, en presente.": "Scrivi come ti piacerebbe sentirti tra un anno, al presente.",
    "Suelta un objeto, una idea o una rutina que ya no te sirve.": "Lascia andare un oggetto, un'idea o una rutina che non ti serve più.",
    "Dedica hoy a mirar lo que sí funciona en tu vida, por pequeño que sea.": "Dedica oggi a guardare ciò che funziona nella tua vita, per quanto piccolo possa essere.",
    "Repite tu frase de sanación mirándote al espejo.": "Ripeti la tua frase di guarigione guardandoti allo specchio.",
    "Haz las paces simbólicamente con una versión más joven de ti.": "Fai pace simbolicamente con una versione più giovane di te.",
    "Comparte con alguien de confianza una parte de este proceso.": "Condividi parte di questo processo con qualcuno di cui ti fidi.",
    "Escribe qué ha cambiado en ti desde el día 1, aunque sea sutil.": "Scrivi cosa è cambiato in te dal giorno 1, anche se sottile.",
    "Celebra haber llegado hasta aquí. Escribe una promesa amable para tu futuro.": "Festeggia l'essere arrivato fin qui. Scrivi una promessa gentile per il tuo futuro.",

