    "El primer paso siempre requiere valentía, {nombre}. ¿Comenzamos hoy?": "Il primo passo richiede sempre coraggio, {nombre}. Cominciamo oggi?",
    "Estás sembrando una hermosa semilla de consciencia, {nombre}. Sigue regándola día a día.": "Stai seminando un bellissimo seme di consapevolezza, {nombre}. Continua ad annaffiarlo giorno dopo giorno.",
    "¡Gran constancia! Siente cómo cada práctica aporta ligereza a tu respiración.": "Grande costanza! Senti come ogni pratica dona leggerezza al tuo respiro.",
    "Tu compromiso es un faro de amor propio. Ya has recorrido más de la mitad de tu viaje.": "Il tuo impegno è un faro di amor proprio. Hai già percorso più della metà del tuo viaggio.",
    "La transformación florece en ti, {nombre}. Estás a muy pocos pasos de integrar este hábito sagrado.": "La trasformazione fiorisce in te, {nombre}. Sei a pochissimi passi dall'integrare questa abitudine sacra.",
