    "No registraste una reflexión para este día. Haz clic en Editar si deseas añadirla.": "Non hai registrato una riflessione per questo giorno. Clicca su Modifica per aggiungerla.",
    "✍️ ¡Escribe algo aquí!": "✍️ Scrivi qualcosa qui!",
    "Anota tus sentimientos, descubrimientos o reflexiones del día...": "Annota i tuoi sentimenti, scoperte o riflessioni del giorno...",
