    "¡Bien hecho! Tu práctica del día ha sido registrada.": "Ben fatto! La tua pratica del giorno è stata registrata.",
    "Para ejecutar el análisis, primero escribe alguna entrada en tu diario de bienestar o reflexiones en el reto de 21 días.": "Per eseguire l'analisi, scrivi prima una nota nel tuo diario del benessere o le riflessioni nella sfida di 21 giorni.",
