    // Recommendations Expresión
    "Dedica 5 minutos al inicio del día para escribir de forma libre (sin levantar la pluma del papel) para drenar la rumiación.": "Dedica 5 minuti all'inizio della giornata a scrivere a ruota libera (senza sollevare la penna dal foglio) per drenare la ruminazione.",
    "Acompaña tus prácticas de diario con solfeo de 396Hz para disolver bloqueos y miedos inconscientes.": "Accoppagna le tue pratiche del diario con il solfeggio a 396Hz per dissolvere blocchi e paure inconsce.",
    "Practica la respiración de caja (inhalar 4, retener 4, exhalar 4, retener 4) antes de iniciar tus reflexiones.": "Pratica la respirazione quadrata (inspira 4, trattieni 4, espira 4, trattieni 4) prima di iniziare le tue riflessioni.",
    "Utiliza la escritura como un espacio de compasión, permitiéndote llorar o plasmar tus penas sin culpas ni juicios.": "Usa la scrittura come uno spazio di compassione, permettendoti di piangere o esprimere le tue pene senza colpe o giudizi.",
    "Sintoniza la frecuencia de solfeo de 528Hz para promover la restauración celular de tu estado de ánimo y el amor propio.": "Sintonizzati sulla frequenza di solfeggio a 528Hz per favorire il ripristino cellulare del tuo umore e l'amor proprio.",
    "Agrega una sección fija al final de cada escrito donde menciones una sola cosa por la que sientas aprecio sincero hoy.": "Aggiungi una sezione fissa alla fine di ogni scritto in cui menzioni una sola cosa per cui provi sincero apprezzamento oggi.",
    "Escribe sobre tu enojo de forma explícita, arrugando o rompiendo el papel después (si es físico) para dar salida física a la emoción.": "Scrivi esplicitamente della tua rabbia, spiegazzando o strappando la carta dopo (se fisica) per dare uno sfogo fisico all'emozione.",
    "Usa solfeo de 417Hz para sintonizar con la limpieza de energías estancadas y facilitar la aceptación del cambio.": "Usa il solfeggio a 417Hz per sintonizzarti con la pulizia delle energie stagnanti e facilitare l'accettazione del cambiamento.",
    "Introduce pausas conscientes de silencio absoluto de 1 minuto antes de responder a situaciones tensas.": "Introduci pause consapevoli di silenzio assoluto di 1 minuto prima di rispondere a situazioni tese.",
    "¡Excelente balance! Expande tu bienestar describiendo a detalle los rostros, olores y sensaciones de los momentos felices.": "Eccellente equilibrio! Espandi il tuo benessere descrivendo in dettaglio i volti, i profumi e le sensazioni dei momenti felici.",
    "Sintoniza frecuencias de 639Hz y 852Hz para elevar tu intuición y fortalecer tus conexiones interpersonales.": "Sintonizzati sulle frequenze 639Hz e 852Hz per elevare la tua intuizione e rafforzare le tue relazioni interpersonali.",
    "Comparte un pensamiento de gratitud con alguien de tu entorno para contagiar y amplificar tu bienestar.": "Condividi un pensiero di gratitudine con qualcuno nel tuo ambiente per contagiare e amplificare il tuo benessere.",
    "Mantén la constancia en tu registro diario. La regularidad es la clave para la auto-consciencia.": "Mantieni la costanza nel tuo registro quotidiano. La regolarità è la chiave per l'autoconsapevolezza.",
    "Prueba variar los temas de tu diario alternando entre relatos de tu día y descripciones puramente emocionales o corporales.": "Prova a variare i temi del tuo diario alternando i racconti della tua giornata con descrizioni puramente emotive o corporee.",
    "Usa solfeo de 432Hz o 528Hz de fondo para sintonizar con los armónicos naturales del entorno.": "Usa il solfeggio a 432Hz o 528Hz in sottofondo per sintonizzarti con le armoniche naturali dell'ambiente.",

    // Recommendations Entorno
    "Crea una rutina de desconexión digital absoluta al menos 45 minutos antes de dormir.": "Crea una routine di disconnessione digitale assoluta almeno 45 minuti prima di dormire.",
    "Introduce difusores con esencia de lavanda, bergamota o manzanilla en tu espacio de descanso.": "Introduci diffusori con essenza di lavanda, bergamotto o camomilla nel tuo spazio di riposo.",
    "Mantén luces cálidas y tenues por la noche para indicarle a tu sistema nervioso que está seguro.": "Mantieni luci calde e soffuse di notte per indicare al tuo sistema nervoso che è al sicuro.",
    "Busca activamente el contacto con la luz natural durante las mañanas (camina al menos 10 minutos bajo el sol).": "Cerca attivamente il contatto con la luce naturale durante la mattina (cammina almeno 10 minuti sotto il sole).",
    "Introduce plantas de interior 🌱 o flores frescas en tu espacio vital para renovar el aire y la energía visual.": "Introduci piante da interno 🌱 o fiori freschi nel tuo spazio vitale per rinnovare l'aria e l'energia visiva.",
    "Escucha sonidos de agua corriente (lluvia, fuentes) de fondo para facilitar el flujo emocional.": "Ascolta i suoni dello scorrere dell'acqua (pioggia, fontane) in sottofondo per facilitare il flusso emotivo.",
    "Asegura el orden visual en tu mesa o escritorio, ya que el desorden físico incrementa la reactividad mental.": "Assicura l'ordine visivo sul tuo tavolo o scrivania, poiché il disordine fisico aumenta la reattività mentale.",
    "Crea un 'rincón de descarga': un lugar cómodo con cojines donde puedas respirar o descansar sin ruidos molestos.": "Crea un 'angolo di scarico': un posto comodo con cuscini dove poter respirare o riposare senza rumori fastidiosi.",
    "Aromatiza tu espacio con esencias cítricas (limón, naranja) para elevar la claridad mental y refrescar la atmósfera.": "Profuma il tuo spazio con essenze agrumate (limone, arancia) per elevare la chiarezza mentale e rinfrescare l'atmosfera.",
    "Conserva fotos de momentos alegres, seres queridos o frases inspiradoras a la vista en tu habitación.": "Conserva foto di momenti felici, persone care o frasi ispiratrici in vista nella tua stanza.",
    "Ventila tus espacios habitacionales diariamente para permitir la renovación constante de la energía vital.": "Ventila i tuoi spazi abitativi quotidianamente per consentire il rinnovo costante dell'energia vitale.",
    "Utiliza sonidos de cuencos de cuarzo o campanas koshi para purificar acústicamente tu hogar.": "Usa i suoni delle campane di quarzo o dei campanelli koshi per purificare acusticamente la tua casa.",
    "Mantén un espacio de lectura o meditación libre de dispositivos móviles para asegurar un santuario de paz.": "Mantieni uno spazio di lettura o meditazione privo di dispositivi mobili per garantire un santuario di pace.",
    "Prueba usar velas de cera de soja con aromas neutros o maderosos para dar calidez a tus momentos de introspección.": "Prova a usare candele di cera di soia con aromi neutri o legnosi per dare calore ai tuoi momenti di introspezione.",
    "Asegura una postura cómoda y erguida en tu asiento habitual para propiciar el flujo libre de tu respiración.": "Assicura una postura comoda ed eretta sulla tua seduta abituale per favorire il libero flusso del respiro.",

