    "Pausa Consciente": "Pausa consapevole",
    "Inhala por 4s, sostén por 4s, exhala por 4s...": "Inspira per 4s, trattieni per 4s, espira per 4s...",
    "1. Ve a tu pantalla de inicio de iOS, mantén presionada una zona vacía o un ícono hasta que todas las apps comiencen a vibrar.": "1. Vai sulla schermata iniziale di iOS, tieni premuta un'area vuota o un'icona finché le app non iniziano a vibrare.",
    "2. Presiona el botón \"+\" en la esquina superior izquierda.": "2. Premi il pulsante \"+\" nell'angolo in alto a sinistra.",
    "3. Busca y selecciona la aplicación instalada \"¡Suelta!\" de la lista de widgets.": "3. Cerca e seleziona l'app installata \"Lascia andare !\" dall'elenco dei widget.",
    "4. Elige el tamaño que prefieras (Chico o Mediano) y toca en \"Añadir widget\". ¡Listo!": "4. Scegli la dimensione che preferisci (Piccolo o Medio) e tocca \"Aggiungi widget\". Pronto!",
    "1. Mantén presionado cualquier espacio vacío en la pantalla de inicio de tu celular Android.": "1. Tieni premuto qualsiasi spazio vuoto sulla schermata iniziale del tuo telefono Android.",
    "2. Toca la opción Widgets que aparece en el menú inferior.": "2. Tocca l'opzione Widget che appare nel menu in basso.",
    "3. Desplázate hasta encontrar la aplicación instalada \"¡Suelta!\".": "3. Scorri fino a trovare l'app installata \"Lascia andare !\".",
    "4. Mantén presionado el widget elegido, arrástralo hasta la posición que prefieras en tu pantalla principal y suéltalo. ¡Listo!": "4. Tieni premuto il widget scelto, trascinalo nella posizione desiderata sulla schermata principale e rilascialo. Pronto!",
    "Te enviaremos breves notificaciones constantes durante el día para reconectar con tu esencia, motivarte y respirar.": "Ti invieremo brevi notifiche costanti durante il giorno per riconnetterti con la tua essenza, motivarti e respirare.",
    "Enviaremos un correo para guiar tu práctica diaria de transformación.": "Invieremo un'e-mail per guidare la tua pratica quotidiana di trasformazione.",
    "🦉 Presencia Consciente": "🦉 Presenza consapevole",
    "Hola viajero, detén tus pensamientos por 5 segundos. Siente tu respiración y baja los hombros.": "Ciao viaggiatore, ferma i tuoi pensieri per 5 secondi. Senti il respiro e abbassa le spalle.",
    "✨ La Esencia de Hoy": "✨ L'essenza di oggi",
    "Recuerda tu reto de hoy: \"{practica}\". Todo fluye cuando dejas de resistir.": "Ricorda la tua sfida di oggi: \"{practica}\". Tutto scorre quando smetti di resistere.",
    "🌿 ¡Suelta!": "🌿 Lascia andare !",
    "Estás sanando a tu propio ritmo, y cada pequeño paso cuenta. Sigue adelante.": "Stai guarendo al tuo ritmo e ogni piccolo passo conta. Continua così.",
    "💫 Pausa del Alma": "💫 Pausa dell'anima",
    "Inhala paz, exhala tensión. Tu cuerpo y tu mente te agradecen este espacio de conexión.": "Inspira pace, espira tensione. Il tuo corpo e la tua mente ti ringraziano per questo spazio di connessione.",
    "🌟 Un recordatorio cariñoso": "🌟 Un amorevole promemoria",
    "Tu valor no se mide por lo que haces, sino por el amor y la presencia que eres aquí y ahora.": "Il tuo valore non si misura da ciò che fai, ma dall'amore e dalla presenza che sei qui e ora.",
    "Comparte contigo": "Condividi con te stesso",
    "Escuchando": "Ascolto in corso",
    "¿Prefieres que te guiemos?": "Preferisci essere guidato?",
    "Recorre tu vida en tres etapas (infancia, adolescencia, adultez) para desbloquear memorias.": "Ripercorri la tua vita in tre fasi (infanzia, adolescenza, età adulta) per sbloccare i ricordi.",
    "Escribe tu historia aquí... no te preocupes por el formato, solo déjalo salir, o toca el micrófono para contarla en voz alta.": "Scrivi la tua storia qui... non preoccuparti del formato, lasciala scorrere o tocca il microfono per raccontarla a voce alta.",
    "El dictado por voz no está disponible en este navegador — puedes escribir directamente.": "La dettatura vocale non è disponibile in questo browser — puoi scrivere direttamente.",
    "Algoritmo de Análisis de 21 Días": "Algoritmo di analisi di 21 giorni",
    "Análisis personalizado de patrones de escritura y salud emocional": "Analisi personalizzata dei modelli di scrittura e della salute emotiva",
    "Nuestro algoritmo de bienestar analiza la profundidad de tus reflexiones, el volumen de palabras y las frecuencias semánticas emocionales de tus registros para ofrecerte un diagnóstico interactivo y recomendaciones a la medida para tu hogar, trabajo y expresión.": "Il nostro algoritmo di benessere analizza la profondità delle tue riflessioni, il volume delle parole e le frequenze semantiche emotive dei tuoi registri per offrirti una diagnosi interattiva e raccomandazioni personalizzate per la tua casa, il tuo lavoro e la tua espressione.",
    "Ejecutar Algoritmo de Análisis": "Esegui algoritmo di analisi",
    "Procesando patrones...": "Elaborazione dei modelli...",
    "Re-calcular Análisis": "Ricalcola analisi",
