    "Tu profundidad de escritura sugiere un alto nivel de desahogo y conexión consigo mismo.": "La tua profondità di scrittura suggerisce un alto livello di sfogo e connessione con se stessi.",
    "Tu profundidad de escritura sugiere un enfoque puntual y reflexivo.": "La tua profondità di scrittura suggerisce un approccio mirato e riflessivo.",
    "Recomendaciones de Expresión Emocional": "Raccomandazioni di espressione emotiva",
    "Recomendaciones para tu Entorno Personal": "Raccomandazioni per il tuo ambiente personale",
    "Este reporte se encuentra protegido y guardado en tu cuenta segura en la nube (respaldado por la infraestructura empresarial de Google Cloud). Se actualiza dinámicamente con cada re-cálculo.": "Questo rapporto è protetto e salvato nel tuo account cloud sicuro (supportato dall'infrastruttura aziendale di Google Cloud). Si aggiorna dinamicamente a ogni ricalcolo.",
    "Presiona el botón de arriba para que el algoritmo procese tus reflexiones diarias y te ofrezca un diagnóstico semántico detallado.": "Premi il pulsante in alto per fare in modo che l'algoritmo elabori le tue riflessioni quotidiane e ti offra una diagnosi semantica dettagliata.",
    "Infancia": "Infanzia",
    "¿Qué recuerdas de tu infancia? Un momento, un olor, una escena, una emoción que aún vive en ti.": "Cosa ricordi della tua infanzia? Un momento, un profumo, una scena, un'emozione che vive ancora in te.",
    "No hay respuesta correcta. Lo que venga primero suele ser lo más honesto.": "Non c'è una risposta corretta. Quello que arriva per primo di solito è il più onesto.",
    "Adolescencia": "Adolescenza",
    "¿Qué marcó tu adolescencia? Algo que aprendiste, algo que dolió, algo que aún cargas.": "Cosa ha segnato la tua adolescenza? Qualcosa che hai imparato, qualcosa che ha fatto male, qualcosa che porti ancora dentro.",
    "Piensa en un momento que hoy, mirándolo, todavía te mueve algo por dentro.": "Pensa a un momento che oggi, guardandolo, ti smuove ancora qualcosa dentro.",
    "Adultez": "Età adulta",
    "¿Cómo llegaste a ser quien eres hoy? Qué has soltado, qué te falta soltar.": "Come sei diventato chi sei oggi? Cosa hai lasciato andare, cosa devi ancora lasciare andare.",
    "Puedes hablar del presente, de lo reciente, o de aquello que sigue pendiente contigo.": "Puoi parlare del presente, del passato recente o di ciò che rimane in sospeso con te stesso.",
