    "Soledad, resentimiento, desconfianza y aislamiento social o familiar.": "Solitudine, risentimento, diffidenza e isolamento sociale o familiare.",
    "Fomenta la comunicación fluida, la empatía y la tolerancia en las relaciones humanas. Es excelente para superar tensiones interpersonales y sanar heridas por distancia.": "Favorisce una comunicazione fluida, l'empatia e la tolleranza nelle relazioni umane. È eccellente per superare le tensioni interpersonali e guarire le ferite causate dalla distanza.",
    "Actúa como un purificador mental para disolver pensamientos repetitivos o tóxicos. Impulsa la libre expresión y el desarrollo de soluciones intuitivas.": "Agisce come un purificatore mentale per dissolvere pensieri ripetitivi o tossici. Favorisce la libera espressione e lo sviluppo di soluzioni intuitive.",
