    "Esta lectura es un acompañamiento emocional. Prioriza siempre la consulta con un profesional ante cualquier síntoma físico o psicológico.": "Questa lettura è un supporto emotivo. Dai sempre la priorità a una consulenza professionale in caso di sintomi fisici o psicologici.",
    "Si quieres profundizar": "Se desideri approfondire",
    "Otras posibles causas": "Altre possibili cause",
    "A veces un conflicto tiene más de un origen. Sin afirmar que sea tu caso, algunas situaciones que suelen acompañar a": "A volte un conflitto ha più di un'origine. Senza affermare che sia il tuo caso, alcune situazioni che spesso accompagnano",
    "son:": "sono:",
    "Esta lectura es una redacción propia de ¡Suelta!, inspirada en el enfoque simbólico de la biodescodificación. Si te interesa profundizar en este enfoque, estas son obras de referencia reconocidas en el tema:": "Questa lettura è una redazione originale di Lascia andare !, ispirata all'approccio simbolico della biodecodifica. Se sei interessato ad approfondire questo approccio, queste sono opere di riferimento riconosciute:",
    "Bienvenido a tu nuevo refugio": "Benvenuto nel tuo nuovo rifugio",
    "Tu cuenta ha sido creada. Prepárate para iniciar un viaje de autoconocimiento. Aquí aprenderás a escuchar tus emociones sin juicios y a soltar lo que ya no te sirve.": "Il tuo account è stato creato. Preparati a iniziare un viaggio di conoscenza di te stesso. Qui imparerai ad ascoltare le tue emozioni senza giudizio e a lasciare andare.",
    "Profundiza en tu proceso": "Approfondisci il tuo percorso",
    "Puedes usar ¡Suelta! gratuitamente para dar tus primeros pasos. Nuestra suscripción Premium te ofrece análisis emocionales completos, acceso a todos los días del reto y un historial ilimitado de tu diario.": "Puoi usare Lascia andare ! gratuitamente per muovere i primi passi. Il nostro abbonamento Premium offre analisi emotive complete, accesso a tutti i giorni della sfida e uno storico illimitato del diario.",
    "Tu camino, a tu ritmo": "La tua strada, al tuo ritmo",
    "A continuación te mostraremos nuestros planes. Elige el que mejor te acompañe hoy; siempre podrás comenzar gratis y evolucionar cuando estés listo.": "Di seguito ti mostreremo i nostri piani. Scegli quello più adatto a te oggi; puoi sempre iniziare gratis e passare oltre quando sei pronto.",
    "Ver planes": "Vedi piani",
    "Para garantizar tu máxima privacidad y blindaje de datos, LA ^ VACHE **no solicita, gestiona ni almacena** tus números de tarjeta de crédito. La compra se procesará de forma segura a través de la pasarela de pagos nativa del sistema operativo de tu dispositivo móvil.": "Per garantire la massima privacy e la protezione dei dati, LA ^ VACHE **non richiede, non gestisce né memorizza** i numeri della tua carta di credito. L'acquisto sarà elaborato in modo sicuro tramite il gateway nativo del tuo dispositivo.",
