    // Added comprehensive translations for CNV, Questionnaires, Tarot & Interactive Tour
    "✨ ¡Te damos la bienvenida a ¡Suelta! ✨": "✨ Ti diamo il benvenuto su Lascia andare ! ✨",
    "Este es tu santuario digital de autodescubrimiento y liberación emocional. Integraremos la biodescodificación, la epigenética y las constelaciones para sanar el origen emocional de tus tensiones. Pulsa 'Comenzar Tour' para iniciar.": "Questo è il tuo santuario digitale per la scoperta di sé e la liberazione emotiva. Integriamo biodecodifica, epigenetica e costellazioni per sciogliere l'origine delle tue tensioni. Tocca 'Inizia il tour'.",
    "🔍 Paso 1: Elige tu Sintonización": "🔍 Passo 1: Scegli la tua sintonizzazione",
    "En la pantalla de Inicio, selecciona tus áreas de sintonía de hoy. ¡Pruébalo ahora! Toca la opción 'Cuéntame tu historia' resaltada abajo.": "Nella schermata Home, seleziona le tue aree di sintonizzazione di oggi. Tocca l'opzione evidenziata 'Raccontami la tua storia'.",
    "Toca 'Cuéntame tu historia' en la lista de opciones.": "Tocca 'Raccontami la tua storia' nell'elenco.",
    "🚀 Paso 2: El Botón Continuar": "🚀 Passo 2: Il pulsante Continua",
    "Cuando selecciones al menos una opción, el botón de Continuar se iluminará con un brillo ámbar especial 👇 para llevarte al análisis completo.": "Selezionata almeno un'opzione, il pulsante Continua si illuminerà d'ambra 👇 per portarti all'analisi completa.",
    "Presiona el botón parpadeante 'Continuar con 1 seleccionada' abajo.": "Premi il pulsante lampeggiante 'Continua con 1 selezionata' in basso.",
    "📅 Paso 3: Reto de 21 Días": "📅 Passo 3: Sfida di 21 Giorni",
    "Tu mente requiere 21 días para reprogramar viejos patrones. En la pestaña 'Mi Reto' tienes acceso a audios diarios, afirmaciones y progreso áureo.": "La mente necessita di 21 giorni per riprogrammare vecchi schemi. Nella scheda 'La mia Sfida' trovi audio giornalieri, affermazioni e progressi.",
    "Toca la pestaña 'Mi Reto' en la barra inferior.": "Tocca la scheda 'La mia Sfida' nella barra inferiore.",
    "✍️ Paso 4: Escribe tu Reflexión Diaria": "✍️ Passo 4: Scrivi la tua riflessione quotidiana",
    "Cada día del Reto incluye un espacio de escritura terapéutica. Intenta escribir cómo te sientes hoy en la casilla de texto.": "Ogni giorno della Sfida include uno spazio di scrittura terapeutica. Prova a scrivere come ti senti nel riquadro.",
    "Escribe al menos 3 letras en la casilla '¿Cómo te sientes con esta revelación?'.": "Scrivi almeno 3 lettere nella casella 'Come ti senti con questa rivelazione?'.",
    "🌿 Paso 5: Registra y Completa el Día": "🌿 Passo 5: Registra e completa il giorno",
    "Una vez escrita tu reflexión, toca 'Completar práctica de hoy' 👇 para encender tu racha de conexión, acumular progreso y actualizar tu calendario.": "Dopo aver scritto, tocca 'Completa la pratica di oggi' 👇 per alimentare i tuoi progressi e aggiornare il calendario.",
    "Presiona el botón 'Completar práctica de hoy' para registrar tu avance.": "Premi il pulsante 'Completa la pratica di oggi' per salvare il tuo avanzamento.",
    "🧘 Paso 6: Recursos de Calma Inmediata": "🧘 Passo 6: Strumenti di calma immediata",
    "Si sufres de ansiedad o síntomas físicos de repente, el módulo 'Calma' ofrece alivio instantáneo libre y sin límites. Toca 'Calma' abajo.": "In caso di ansia o sintomi fisici improvvisi, il modulo 'Calma' offre sollievo istantaneo e illimitato. Tocca 'Calma' in basso.",
    "Toca la pestaña 'Calma' en la barra inferior.": "Tocca la scheda 'Calma' nella barra inferiore.",
    "🌬️ Paso 7: Elige Respiración Guiada": "🌬️ Passo 7: Scegli la respirazione guidata",
    "Regula tu sistema nervioso autónomo de inmediato. Toca la tarjeta de 'Respiración guiada' parpadeante 👈.": "Regola il tuo sistema nervoso autonomo immediatamente. Tocca la scheda 'Respirazione guidata' 👈.",
    "Toca la opción 'Respiración guiada' con el borde brillante.": "Tocca l'opzione 'Respirazione guidata' evidenziata.",
    "🎶 Paso 8: Pulso Vibracional Solfeggio": "🎶 Passo 8: Frequenze Solfeggio",
    "Sintoniza frecuencias sanadoras de fondo. El círculo áureo se expandirá y contraerá para guiar tus inhalaciones. Toca 'Comenzar'.": "Ascolta frequenze rigeneranti. Il cerchio dorato si espande e contrae per guidare il tuo respiro. Tocca 'Inizia'.",
    "Presiona el botón dorado 'Comenzar' dentro del círculo de respiración.": "Premi il pulsante dorato 'Inizia' all'interno del cerchio.",
    "📖 Paso 9: Biblioteca de Perspectivas": "📖 Passo 9: Biblioteca delle prospettive",
    "Tu cuerpo habla lo que tu mente calla. El Diccionario Biológico te permite comprender la raíz de tus síntomas. Toca 'Perspectivas' abajo.": "Il corpo parla quando la mente tace. Il Dizionario Biologico ti aiuta a capire la radice dei sintomi. Tocca 'Prospettive'.",
    "Toca la pestaña 'Perspectivas' en la barra inferior.": "Tocca la scheda 'Prospettive' nella barra inferiore.",
    "🌳 Paso 10: Árbol Genealógico Interactivo": "🌳 Passo 10: Albero genealogico interattivo",
    "Grafica tu propio clan familiar en el Árbol Genealógico para identificar lealtades invisibles y secretos heredados.": "Disegna il tuo albero genealogico per identificare lealtà invisibili e dinamiche tramandate.",
    "Toca la opción dorada parpadeante 'Constelación familiar'.": "Tocca l'opzione dorata 'Costellazione familiare'.",
    "👥 Paso 11: Acompañamiento de Especialistas": "👥 Passo 11: Supporto di specialisti",
    "Si requieres contención personalizada, te contactamos de forma directa con terapeutas y psicólogos acreditados. Toca 'Expertos' abajo.": "Se desideri un percorso su misura, ti mettiamo in contatto con terapeuti e psicologi accreditati. Tocca 'Esperti'.",
    "Toca la pestaña 'Expertos' en la barra inferior.": "Tocca la scheda 'Esperti' nella barra inferiore.",
    "🌸 ¡Onboarding Listo para Ti! 🌸": "🌸 Guida completata con successo! 🌸",
    "¡Felicidades! Has completado la guía de aprendizaje interactiva de ¡Suelta!. Estás listo para reprogramar tu biología y sanar con amor.": "Congratulazioni! Hai completato la guida interattiva di Lascia andare !. Sei pronta/o a prenderti cura di te con amorevole consapevolezza.",
