    "Pequeños cuestionarios para conocerte mejor. No son un evaluación de bienestar: son un espejo más para tu proceso.": "Piccoli questionari per conoscerti meglio. Non sono un test diagnostico, ma uno specchio utile per il tuo cammino.",
