// Active global language state for the entire application
let activeLanguage = "es";

export function setGlobalLanguage(lang) {
  activeLanguage = lang || "es";
}

export function getGlobalLanguage() {
  return activeLanguage;
}

// Translates a dictionary entry on the fly to another language if it has curated translations.
// If it's another entry, translates the labels but maintains the original Spanish terms or provides a readable translation layout.
export function translateCard(card, lang) {
  const currentLang = lang || activeLanguage;
  if (!card) return null;
  if (!currentLang || currentLang === "es") return card;

  // Check if we have curated translations for this specific card
  const cardId = card.id || "";
  let curated = CURATED_CARDS[cardId];
  if (!curated && card.keywords) {
    for (const kw of card.keywords) {
      if (CURATED_CARDS[kw]) {
        curated = CURATED_CARDS[kw];
        break;
      }
    }
  }

  if (curated && curated[currentLang]) {
    return {
      ...card,
      termino: curated[currentLang].termino || t(card.termino, currentLang),
      sentido: curated[currentLang].sentido || t(card.sentido, currentLang),
      enfoque: curated[currentLang].enfoque || t(card.enfoque, currentLang),
      otrasCausas: curated[currentLang].otrasCausas || (card.otrasCausas ? card.otrasCausas.map(c => t(c, currentLang) || c) : []),
    };
  }

  // Fallback: translate using t() dictionary lookup for term, meaning, and causes
  return {
    ...card,
    termino: t(card.termino, currentLang) || card.termino,
    sentido: t(card.sentido, currentLang) || card.sentido,
    enfoque: t(card.enfoque, currentLang) || card.enfoque,
    otrasCausas: card.otrasCausas ? card.otrasCausas.map(c => t(c, currentLang) || c) : [],
  };
}

