export function translateSign(signName, lang) {
  const currentLang = lang || activeLanguage;
  if (!signName || !currentLang || currentLang === "es") return { signo: signName };
  const found = ZODIACO_TRANSLATIONS[signName];
  return found ? found[currentLang] : { signo: signName };
}

