export function translateTonalli(tonalliSignObj, lang) {
  const currentLang = lang || activeLanguage;
  if (!tonalliSignObj || !currentLang || currentLang === "es") return tonalliSignObj;
  const found = TONAL_TRANSLATIONS[tonalliSignObj.nombre];
  if (found && found[currentLang]) {
    return {
      ...tonalliSignObj,
      es: found[currentLang].es,
      energia: found[currentLang].energia
    };
  }
  return tonalliSignObj;
}

// Translations for Numerology Camino de Vida
export const NUMERO_TRANSLATIONS = {
  1: {
    en: { nombre: "The Initiator", sentido: "1 is the energy of beginning: leadership, independence, and the strength to carve a path where there was none before. Those who carry this number usually feel called to decide for themselves, rather than follow other people's instructions.", enfoque: "Practice trusting your first decision before asking for too many external opinions." },
    fr: { nombre: "L'Initiateur", sentido: "Le 1 est l'énergie du commencement : leadership, indépendance et force d'ouvrir une voie là où il n'y en avait pas auparavant. Ceux qui portent ce nombre se sentent généralement appelés à décider par eux-mêmes, plutôt qu'à suivre les instructions d'autrui.", enfoque: "Entraînez-vous à faire confiance à votre première décision avant de solliciter trop d'avis extérieurs." },
    it: { nombre: "L'Iniziatore", sentido: "L'1 è l'energia dell'inizio: leadership, indipendenza e la forza di aprire una strada dove prima non c'era nulla. Chi porta questo numero di solito si sente chiamato a decidere da sé, piuttosto che seguire le istruzioni altrui.", enfoque: "Esercitati a fidarti della tua prima decisione prima di chiedere troppi pareri esterni." }
  },
  2: {
    en: { nombre: "The Diplomat", sentido: "2 is the energy of the bond: cooperation, sensitivity, and the ability to support others without losing oneself in the process. It usually manifests as a fine attention to what the other person needs, sometimes more than what one needs.", enfoque: "Practice naming your own needs with the same clarity that you perceive those of others." },
    fr: { nombre: "Le Diplomate", sentido: "Le 2 est l'énergie du lien : coopération, sensibilité et capacité à soutenir les autres sans s'y perdre. Cela se manifeste généralement par une attention fine aux besoins d'autrui, parfois plus qu'aux siens.", enfoque: "Entraînez-vous à exprimer vos propres besoins avec la même clarté que vous percevez ceux des autres." },
    it: { nombre: "Il Diplomatico", sentido: "Il 2 è l'energia del legame: cooperazione, sensibilità e capacità di sostenere gli altri senza perdersi nel processo. Di solito si manifesta come un'attenzione raffinata a ciò di cui l'altro ha bisogno, a volte più che a ciò di cui si ha bisogno per sé.", enfoque: "Esercitati a nominare i tuoi bisogni con la stessa chiarezza con cui percepisci quelli altrui." }
  },
  3: {
    en: { nombre: "The Communicator", sentido: "3 is the energy of expression: creativity, joy, and the need for what is felt inside to find a way out — through speech, art, conversation. When blocked, it usually feels like a weight in the chest or throat.", enfoque: "Practice sharing one idea or feeling a week without polishing it before saying it." },
    fr: { nombre: "Le Communicateur", sentido: "Le 3 est l'énergie de l'expression : créativité, joie et besoin de faire sortir ce que l'on ressent à l'intérieur — parole, art, conversation. Lorsqu'elle est bloquée, elle se ressent généralement comme un poids dans la poitrine ou la gorge.", enfoque: "Entraînez-vous à partager une idée ou un sentiment par semaine sans le peaufiner avant de le dire." },
    it: { nombre: "Il Comunicatore", sentido: "Il 3 è l'energia dell'espressione: creatività, gioia e necessità che ciò che si prova dentro trovi una via d'uscita — parola, arte, conversazione. Quando è bloccata, di solito si avverte come un peso al petto o alla gola.", enfoque: "Esercitati a condividere un'idea o un sentimento alla settimana senza perfezionarlo prima di esprimerlo." }
  },
  4: {
    en: { nombre: "The Builder", sentido: "4 is the energy of structure: discipline, order, and the patience to build something that lasts. Those who carry this number are often the silent support of their families or teams, although they rarely acknowledge it out loud.", enfoque: "Practice asking for recognition for what you support, instead of waiting for it to be noticed on its own." },
    fr: { nombre: "Le Bâtisseur", sentido: "Le 4 est l'énergie de la structure : discipline, ordre et patience de construire quelque chose qui dure. Ceux qui portent ce nombre sont souvent le soutien silencieux de leur famille ou de leur équipe, bien qu'ils le reconnaissent rarement à haute voix.", enfoque: "Entraînez-vous à demander de la reconnaissance pour ce que vous soutenez, au lieu d'attendre que cela soit remarqué tout seul." },
    it: { nombre: "Il Costruttore", sentido: "Il 4 è l'energia della struttura: disciplina, ordine e la pazienza di costruire qualcosa che duri. Chi porta questo numero è spesso il pilastro silenzioso della propria famiglia o del proprio team, anche se raramente lo riconosce ad alta voce.", enfoque: "Esercitati a chiedere un riconoscimento per ciò che sostieni, invece di aspettare che venga notato da solo." }
  },
  5: {
    en: { nombre: "The Explorer", sentido: "5 is the energy of movement: freedom, change, and a curiosity that does not tolerate prolonged routine. Forced stillness usually feels, for this number, like a subtle form of confinement.", enfoque: "Practice introducing a small, deliberate change when you feel everything has become predictable." },
    fr: { nombre: "L'Explorateur", sentido: "Le 5 est l'énergie du mouvement : liberté, changement et curiosité qui tolère mal la routine prolongée. Pour ce nombre, l'immobilité forcée ressemble généralement à une forme subtile d'enfermement.", enfoque: "Entraînez-vous à introduire un petit changement délibéré lorsque vous sentez que tout est devenu trop prévisible." },
    it: { nombre: "L'Esploratore", sentido: "Il 5 è l'energia del movimento: libertà, cambiamento e una curiosità che non tollera bene la routine prolungata. L'immobilità forzata di solito si avverte, per questo numero, come una sottile forma di reclusione.", enfoque: "Esercitati a introdurre un piccolo e deliberato cambiamento quando senti che tutto è diventato troppo prevedibile." }
  },
  6: {
    en: { nombre: "The Nurturer", sentido: "6 is the energy of the home: responsibility, care, and a deep sense of community and family. Its most common challenge is confusing love with the obligation to solve other people's lives.", enfoque: "Practice caring without rescuing: ask yourself if what you are about to do was asked of you, or if you assumed it on your own." },
    fr: { nombre: "Le Protecteur", sentido: "Le 6 est l'énergie du foyer : responsabilité, soin et sens profond de la communauté et de la famille. Son défi le plus commun est de confondre l'amour avec l'obligation de résoudre la vie des autres.", enfoque: "Entraînez-vous à prendre soin sans sauver : demandez-vous si ce que vous vous apprêtez à faire vous a été demandé, ou si vous l'avez assumé de vous-même." },
    it: { nombre: "Il Custode", sentido: "Il 6 è l'energia della casa: responsabilità, cura e un senso profondo di comunità e famiglia. La sfida più comune è confondere l'amore con l'obbligo di risolvere la vita altrui.", enfoque: "Esercitati a prenderti cura senza salvare: chiediti se quello che stai per fare ti è stato chiesto, o se lo hai assunto di tua iniziativa." }
  },
  7: {
    en: { nombre: "The Seeker", sentido: "7 is the energy of introspection: analysis, spirituality, and a genuine need to understand the 'why' behind things, not just the 'what'. It usually requires more solitude than most to process life.", enfoque: "Practice allowing yourself that time alone without guilt, instead of forcing yourself to always be available." },
    fr: { nombre: "Le Chercheur", sentido: "Le 7 est l'énergie de l'introspection : analyse, spiritualité et besoin authentique de comprendre le 'pourquoi' des choses, pas seulement le 'quoi'. Il a généralement besoin de plus de solitude que la plupart pour digérer ce qu'il vit.", enfoque: "Entraînez-vous à vous accorder ce temps pour vous sans culpabilité, au lieu de vous forcer à être toujours disponible." },
    it: { nombre: "Il Ricercatore", sentido: "Il 7 è l'energia dell'introspezione: analisi, spiritualità e un sincero bisogno di capire il 'perché' dietro le cose, non solo il 'cosa'. Di solito richiede più solitudine rispetto alla maggior parte delle persone per elaborare ciò che vive.", enfoque: "Esercitati a concederti quel tempo da sola senza sensi di colpa, invece di forzarti ad essere sempre disponibile." }
  },
  8: {
    en: { nombre: "The Achiever", sentido: "8 is the energy of achievement: personal power, material abundance, and the ability to materialize big visions. Its central learning is distinguishing the power that builds from the power that controls.", enfoque: "Practice reviewing whether your ultimate decisions come from abundance or the fear of not having enough." },
    fr: { nombre: "Le Réalisateur", sentido: "Le 8 est l'énergie de l'accomplissement : pouvoir personnel, abondance matérielle et capacité à concrétiser de grandes visions. Son apprentissage central est de distinguer le pouvoir qui construit du pouvoir qui contrôle.", enfoque: "Entraînez-vous à vérifier si vos décisions ultimes viennent de l'abondance ou de la peur de ne pas avoir assez." },
    it: { nombre: "Il Realizzatore", sentido: "L'8 è l'energia della realizzazione: potere personale, abbondanza materiale e capacità di concretizzare grandi visioni. L'apprendimento centrale di solito sta nel distinguere il potere che costruisce dal potere che controlla.", enfoque: "Esercitati a verificare se le tue decisioni finali derivano dall'abbondanza o dalla paura di non avere abbastanza." }
  },
  9: {
    en: { nombre: "The Compassionate", sentido: "9 is the energy of closing cycles: broad compassion, service to others, and the wisdom that comes after having lived much. It usually carries a special sensitivity towards others' suffering, sometimes more than towards one's own.", enfoque: "Practice closing a pending cycle before opening a new one; the 9 heals by letting go, not accumulating." },
    fr: { nombre: "L'Altruiste", sentido: "Le 9 est l'énergie de la clôture des cycles : grande compassion, service aux autres et sagesse acquise après avoir beaucoup vécu. Il porte généralement une sensibilité particulière face à la souffrance d'autrui, parfois plus qu'à la sienne.", enfoque: "Entraînez-vous à clore un cycle en suspens avant d'en ouvrir un nouveau ; le 9 guérit en lâchant prise, pas en accumulant." },
    it: { nombre: "Il Compassionevole", sentido: "Il 9 è l'energia della chiusura dei cicli: profonda compassione, servizio agli altri e la saggezza che deriva dall'aver vissuto molto. Di solito porta con sé una sensibilità speciale verso la sofferenza altrui, a volte più che verso la propria.", enfoque: "Esercitati a chiudere un ciclo in sospeso prima di aprirne uno nuovo; il 9 guarisce lasciando andare, non accumulando." }
  },
  11: {
    en: { nombre: "The Intuitive (master number)", sentido: "11 is a master number: elevated intuition, almost prophetic sensitivity, and a natural ability to inspire others by your own example. This same sensitivity can become overwhelming if you don't learn to set clear energetic boundaries.", enfoque: "Practice protecting your energy as much as you trust your intuition; both are part of the same gift." },
    fr: { nombre: "L'Intuitif (nombre maître)", sentido: "Le 11 est un nombre maître : intuition élevée, sensibilité presque prophétique et capacité naturelle à inspirer les autres par son propre exemple. Cette même sensibilité peut devenir écrasante si l'on n'apprend pas à poser des limites énergétiques claires.", enfoque: "Entraînez-vous à protéger votre énergie autant que vous faites confiance à votre intuition ; les deux font partie du même don." },
    it: { nombre: "L'Intuitivo (numero maestro)", sentido: "L'11 è un numero maestro: intuito elevato, sensibilità quasi profetica e una naturale capacità di ispirare gli altri con il proprio esempio. Questa stessa sensibilità può diventare travolgente se non si impara a porre chiari limiti energetici.", enfoque: "Esercitati a proteggere la tua energia tanto quanto ti fidi del tuo intuito; entrambi fanno parte dello stesso dono." }
  },
  22: {
    en: { nombre: "The Master Builder (master number)", sentido: "22 is a master number: the ability to take a grand, idealistic vision and turn it into concrete reality, on a large scale. The challenge is usually the burden of feeling that every project must be monumental to be worth doing.", enfoque: "Practice allowing yourself to build also in small ways, without everything having to change the world." },
    fr: { nombre: "Le Maître Bâtisseur (nombre maître)", sentido: "Le 22 est un nombre maître : capacité à prendre une vision grande et idéaliste pour en faire une réalité concrète, à grande échelle. Le défi réside généralement dans le poids de sentir que chaque projet doit être monumental pour en valoir la peine.", enfoque: "Entraînez-vous à construire aussi à petite échelle, sans que tout ait besoin de changer le monde." },
    it: { nombre: "Il Maestro Costruttore (numero maestro)", sentido: "Il 22 è un numero maestro: la capacità di prendere una visione grande e idealistica e trasformarla in realtà concreta, su larga scala. La sfida di solito sta nel peso di sentire che ogni progetto debba essere monumentale per valerne la pena.", enfoque: "Esercitati a concederti di costruire anche in piccolo, senza che ogni cosa debba per forza cambiare il mondo." }
  },
  33: {
    en: { nombre: "The Master Healer (master number)", sentido: "33 is a master number: unconditional service, elevated compassion, and a natural calling to accompany others' healing. The risk is giving so much that you forget to heal yourself first.", enfoque: "Practice receiving care with the same generosity with which you give it to others." },
    fr: { nombre: "Le Maître Guérisseur (nombre maître)", sentido: "Le 33 est un nombre maître : service inconditionnel, haute compassion et vocation naturelle à accompagner la guérison des autres. Le risque est de tant donner que l'on en oublie de se guérir soi-même d'abord.", enfoque: "Entraînez-vous à recevoir du soin avec la même générosité que vous en donnez aux autres." },
    it: { nombre: "Il Maestro Guaritore (numero maestro)", sentido: "Il 33 è un numero maestro: servizio incondizionato, compassione elevata e una naturale vocazione ad accompagnare la guarigione degli altri. Il rischio è dare così tanto da dimenticarsi di guarire se stesse prima.", enfoque: "Esercitati a ricevere cura con la stessa generosità con cui la offri agli altri." }
  }
};

export function translateNumber(numberKey, lang) {
  const currentLang = lang || activeLanguage;
  if (!numberKey || !currentLang || currentLang === "es") return { nombre: String(numberKey) };
  const found = NUMERO_TRANSLATIONS[numberKey];
  return found ? found[currentLang] : { nombre: String(numberKey) };
}

// Global translate helper
export function t(key, lang) {
  if (!key) return key;
  const currentLang = lang || activeLanguage;
  if (SOMATIC_TRANSLATIONS && SOMATIC_TRANSLATIONS[currentLang] && SOMATIC_TRANSLATIONS[currentLang][key] !== undefined) {
    return SOMATIC_TRANSLATIONS[currentLang][key];
  }
  if (FORM_AND_QUIZ_TRANSLATIONS && FORM_AND_QUIZ_TRANSLATIONS[currentLang] && FORM_AND_QUIZ_TRANSLATIONS[currentLang][key] !== undefined) {
    return FORM_AND_QUIZ_TRANSLATIONS[currentLang][key];
  }
  if (APP_UI_TRANSLATIONS && APP_UI_TRANSLATIONS[currentLang] && APP_UI_TRANSLATIONS[currentLang][key] !== undefined) {
    return APP_UI_TRANSLATIONS[currentLang][key];
  }
  if (!TRANSLATIONS[currentLang]) return key;
  const translated = TRANSLATIONS[currentLang][key];
  return translated !== undefined ? translated : key;
}
